quests[51176] = { id = 51176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisst" }
quests[51177] = { id = 51177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektionen der Verfluchten", description = "Als ich hier verkleidet ankam, hielten die Bluttrolle mich für einen Boten ihres Blutgottes.\n\nDiese Chance habe ich ergriffen und ihren primitiven Glauben genutzt.\n\nIch bin hergekommen, um den Handel zu ermöglichen und zu erfahren, wie wir gemeinsam gegen die Horde vorgehen könnten.\n\nDoch was ich erfahren habe, war noch viel faszinierender. Ich werde es Euch zeigen.", sourceObjective = "Findet heraus, wie Hauptmann Conrad vorangekommen ist.", completion = "Es ist eine grässliche Situation, {name}. Ich war auf einer Rettungs- oder doch zumindest einer Bergungsmission. Doch als ich erfuhr, was mit den Unseren geschah... Ich war verstört.\n\nDoch da können wir nichts mehr dran ändern. Ich werde einen Bericht an Halford senden. Diesmal bleibt nichts für Euch zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51178] = { id = 51178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einhundert Trolle im Weg" }
quests[51179] = { id = 51179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritwahn" }
quests[51180] = { id = 51180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Anleitung" }
