quests[51185] = { id = 51185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritermächtigung" }
quests[51190] = { id = 51190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Atempause verschaffen", description = "Doch es gibt jetzt dringlichere Probleme.\n\nDie Verlassenen sind aufgetaucht und halten uns davon ab, unsere Leute zu retten. Alle meine Soldaten sind entweder verletzt, erschöpft oder einfach nicht in der Lage zu kämpfen.\n\nEs scheint, als hätten die heimischen Trolle sich mit ihnen zusammengetan, und meine Kapazitäten sind erschöpft.\n\nAlso tötet die Horde. Tötet die Zandalari. Tötet sie alle.", sourceObjective = "Tötet 8 Verlassene und 8 Zandalari in Talanjis Tadel.", completion = "Endlich ein paar Schwachköpfe weniger, um die wir uns sorgen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51191] = { id = 51191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet sie alle", description = "Verstärkung? Oh, dem Licht sei Dank!\n\nWir haben getan, was wir konnten, um die Verletzten zu behandeln, aber wir brauchen Hilfe. Wir brauchen mehr Helfer, die Wunden versorgen oder zumindest Verbände anlegen können.\n\nWie kommt Ihr mit solchen Dingen zurecht? Hier, nehmt diese Verbände und tut, was Ihr könnt, um die Verwundeten zu versorgen.", sourceObjective = "Heilt 8 verletzte Matrosen.", completion = "Ihr würdet einen hervorragenden Sanitäter abgeben. Oder zumindest einen passablen Krankenpfleger.", sourceObjectiveStatus = "unverified-source-field" }
quests[51192] = { id = 51192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorratsmangel", description = "Nahrung, Holz, Stoff... Uns fehlt einfach alles. Nun, mir fehlt es natürlich an Größe, aber das hat mich noch nie aufgehalten.\n\nHehe.\n\nSchaut doch mal, ob im Schiffswrack noch etwas gerettet werden kann.", sourceObjective = "Sammelt Vorräte aus dem Schiffswrack.", progress = "Habt Ihr etwas Nützliches gefunden?", completion = "Unglaublich, was wir schaffen können, wenn wir die nötigen Vorräte haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[51193] = { id = 51193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist meiner!", description = "Kommt Ihr, um zu helfen? Ich habe eigentlich nichts... Na ja, vielleicht doch.\n\nIch weiß, es ist nur ein einfacher Hammer. Er hat nichts Besonderes an sich. Aber es ist meiner.\n\nUnd dieser ekelhafte Untote, Alan Hawkins, verspottet mich damit. Ich habe Feorea versprochen, dass ich mich nicht mit ihm anlegen werde. Aber Ihr habt ja nichts Derartiges versprochen.\n\nTötet ihn und holt meinen Hammer zurück.", sourceObjective = "Besorgt Degdods Hammer von Alan Hawkins.", progress = "Macht mir keine Vorwürfe. Das ist mein bester Hammer.", completion = "Ich weiß, er mag nicht wie ein besonderer Hammer wirken. Aber für mich ist er etwas sehr Besonderes.", sourceObjectiveStatus = "unverified-source-field" }
quests[51198] = { id = 51198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düngerdienst" }
quests[51199] = { id = 51199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruhm der Jagd", description = "Seid Ihr wegen des Fests hier, <mein Freund/meine Liebe>?\n\nWir bauen noch auf, aber die Jagd sollte schon begonnen haben.\n\nWenn Ihr teilnehmen wollt, müsst Ihr Anne in der Fuchsbauwaldung aufsuchen. Sie wird Euch alles erklären.\n\nGute Jagd!", sourceObjective = "Trefft Anne Watteck am Rand der Fuchsbauwaldung.", completion = "Ah, Georg hat Euch geschickt! Würdet Ihr gerne an der Jagd teilnehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[51200] = { id = 51200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das schwarze Schaf", description = "Ich geb zu, Milli ist nie zuverlässig der Herde gefolgt. Normalerweise stellt das auch kein Problem dar. Sie wandert ein wenig umher, tut das, was sie möchte, und kehrt dann schließlich wieder zu ihrer Herde zurück.\n\nDoch in letzter Zeit sind die Berge immer gefährlicher geworden, besonders mit all den Wölfen und Riesen in der Gegend. Sie ist schon eine Weile fort und ich mache mir langsam Sorgen.\n\nKönntet Ihr mir bitte helfen, nach ihr zu suchen?", sourceObjective = "Findet und rettet Milli.", completion = "Oh, meine liebe Milli! Ich danke Euch, {name}. Ich stehe in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[51201] = { id = 51201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte des Trolls", description = "Ihr kommt zu einem... interessanten Zeitpunkt, {class}. All meine Schiffe sind zerstört worden. Die Hälfte meiner Männer ist Fischfutter, und den übriggebliebenen geht es kaum besser. Wir sind so gut wie verloren.\n\nUnd doch behält die Allianz die Oberhand.\n\nSchuld an diesem Massaker sind allein die Zandalaritrolle. Ich muss erfahren, wie sie das geschafft haben, bevor wir sie alle töten und von dieser lichtverlassenen Insel fliehen.", sourceObjective = "Sprecht mit dem gefangenen Zandalaritroll, um herauszufinden, wie die Flotte der Allianz versenkt wurde.", progress = "<Thom grinst den vor ihm kauernden Zandalaritroll höhnisch an.>\n\nRedet schon, mieser Grobian!", completion = "Prinzessin... Talanji, sagt Ihr? Verstehe.\n\nDavon wird König Wrynn erfahren. Diese Zandalariprinzessin wird schon noch lernen, was es bedeutet, sich die Allianz zum Feind zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51203] = { id = 51203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Wolfspelz", description = "In letzter Zeit terrorisieren die Wölfe meine Herde. Sie waren nie ein Problem, bis die Riesen kamen und sie aus ihrem normalen Jagdgebiet vertrieben haben.\n\nIch laste Euch nur ungern die Arbeit auf, aber würdet Ihr ein paar von ihnen beseitigen? Wenn sich weniger Wölfe ums Fressen streiten, lassen sie uns vielleicht wieder in Ruhe.", sourceObjective = "Tötet 10 wilde Klingenklauen.", completion = "Jetzt sollte sich meine Herde wieder beruhigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[51204] = { id = 51204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Klingenklauenalpha", description = "Abenteurer gesucht!\n\nDie Wölfe stürzen sich auf meine Herde! Und ich kann sie nicht abwehren.\n\nIch habe einen Wolf gesehen, der deutlich größer war als die anderen. Er schien einige der Angriffe anzuführen.\n\nFür Hilfe in dieser Sache biete ich alles, was ich irgendwie aufbringen kann.\n\n- Hirtin Mühlbach", sourceObjective = "Tötet den Klingenklauenalpha.", completion = "Wow, ich war mir nicht sicher, ob wirklich jemand auf meinen Aufruf reagieren würde. Ich danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[51205] = { id = 51205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattzifist", description = "So habe ich mir das nicht vorgestellt! Ich will wieder die einfachen Zeiten zurück, wo man nur Mehl gemahlen und Met getrunken hat.\n\nUnd als wär's nicht schon schlimm genug, fällt jetzt auch noch eine Armee Ratten über unser Lagerhaus her. Und ich bin wirklich nicht in der Lage, die Viecher auszurotten.\n\nHier, das habe ich von einem irren Gnom, der vor Kurzem im Hafen gelandet ist. Ich dachte, das könnte gegen die Bienen helfen. Vielleicht wollt Ihr ja mal probieren, ob es auch bei den Ratten funktioniert?", sourceObjective = "Sammelt 8 Bilgeratten.", completion = "Ich danke Euch von ganzem Herzen. Ich werde die kleinen Kerle loswerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[51207] = { id = 51207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "W-Ettin, dass...?", description = "Hört zu, ich hab hier jetzt etwas aus den zusätzlichen Zutaten zusammengeschustert.\n\nWaffen haben wir hier nicht wirklich, aber Schießpulver und haufenweise Mehl. Das ist eine überraschend explosive Mischung!\n\nWerft einen dieser Snacks auf diese lästigen Ettins. Das sollte sie lange genug ablenken, um ihnen ordentlich eins überziehen zu können.\n\nIhr dachtet wohl, ich wäre nur eine nette alte Dame, die für Besucher leckere Kekse backt, was? Ha! In vergangenen Zeiten wusste ich ganz gut, wie man es knallen lässt!", sourceObjective = "Benutzt Mehlbomben, um 8 Ettins zu töten.", completion = "{name}, von Euch könnte mein Enkel das ein oder andere lernen. Ihr könnt mich gerne wieder besuchen kommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[51208] = { id = 51208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ährenvolle Aufgabe", description = "Da unser Lagerhaus von Ratten geplündert wurde und die Riesen unsere Lieferungen stehlen, geht uns allmählich das Essen aus.\n\nAls ich auf dem Weg hierher war, sah ich einige Getreidesäcke in der Nähe der zerstörten Wagen herumliegen.\n\nEs wäre wirklich sehr freundlich, wenn Ihr dort draußen so viele davon sammeln würdet, wie Ihr finden könnt.", sourceObjective = "Sammelt 10 Getreidesäcke.", completion = "Wow! Kaum zu glauben, dass Ihr das alles tragen konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[51209] = { id = 51209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächtiger Grokkfaust", sourceObjective = "Setzt den Rattenbeutel ein, um Grokkfaust zu töten.", completion = "Ich kann nicht fassen, dass es wirklich funktioniert hat. Ich war mir sicher, dass wir alle zerquetscht werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[51210] = { id = 51210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprengung der Belagerung" }
quests[51211] = { id = 51211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz von Azeroth", description = "Unsere Welt ist dem Tod geweiht, {name}. Sargeras' Schwert hat eine tiefe Wunde hinterlassen. Ihr Schmerz macht die Elemente rasend!\n\nIch kann die Stimme Azeroths hören, aber sie braucht mehr als ihren Sprecher.\n\nSie braucht ihren Champion.\n\nWeit unter uns liegt ein uraltes Titanengewölbe, die Herzkammer. Ich spüre, dass sie dort mit Euch Zwiesprache zu halten wünscht.\n\nKommt mit mir in die Kammer. Es könnte unsere einzige Chance sein, sie zu retten!", sourceObjective = "Begebt Euch in die Herzkammer und haltet Zwiesprache mit Azeroth.", progress = "Ihr müsst es von Azeroth selbst hören, {name}.", completion = "Das Herz von Azeroth... Das ist der Schlüssel zur Heilung ihrer Wunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[51212] = { id = 51212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kronsteiganwesen: Die Hexenküche" }
quests[51213] = { id = 51213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kronsteiganwesen: Eine Hexe zu viel" }
quests[51214] = { id = 51214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid ein Schatz", description = "Wie Ihr an den herumfliegenden Felsen deutlich sehen könnt, werden wir von diesen schrecklichen Ettins belagert!\n\nIch wäre Euch wirklich sehr dankbar, wenn Ihr uns helfen könntet. Wir können aber nicht hoffen, sie zu besiegen, bevor wir Euch nicht gut vorbereitet haben.\n\nWärt Ihr so lieb und würdet ein paar Dinge für mich im Dorf besorgen? Nur etwas Wasser, ein Sack Mehl und ein Bündel Holzscheite.\n\nIch habe schon meinen Enkel Karl losgeschickt, ein paar andere Dinge zu holen. Aber ich habe schon eine Weile nichts mehr von ihm gehört.", sourceObjective = "Beschafft einen Wassereimer, einen Mehlsack und Holzscheite und kehrt dann zu Marie Fürbittshafen zurück.", completion = "Vielen lieben Dank. Ich wünschte, Karl wäre auch so fleißig.", sourceObjectiveStatus = "unverified-source-field" }
quests[51215] = { id = 51215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziegen melken", description = "Leider produziert Mühlbachs Herde in letzter Zeit nichts. Die armen Dinger müssen wegen der Wölfe, die sich hier herumtreiben, völlig verängstigt sein.\n\nWilde Ziegen streifen durch die Hügel, und im Vergleich zu den Schafen sind sie ziemlich furchtlos.\n\nWenn Ihr welche mit ein paar Jungtieren findet, könnt Ihr sie vielleicht überzeugen, ein wenig ihrer köstlichen Ziegenmilch abzugeben!", sourceObjective = "Sammelt 6 Einheiten Bergziegenmilch.", progress = "Habt Ihr es geschafft, genug Milch zu sammeln?", completion = "Die riecht wundervoll. Ausgezeichnet, ich danke Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[51216] = { id = 51216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kronsteiganwesen: Das Krächzen der Krähe" }
quests[51217] = { id = 51217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Yarsel'ghun", description = "Auf Anordnung der Sturmwacht.\n\nFindet und tötet die Spionin Yarsel'ghun.\n\nDiese fremde Agentin versteckt sich in unserem Land und hat terroristische Angriffe auf die Bewohner des Sturmsangtals zu verantworten.\n\nDie Person, die ihre Existenz beendet, verdient sich eine gebührende Belohnung.", sourceObjective = "Findet und tötet Yarsel'ghun.", completion = "Und wieder etwas weniger Horde in Sturmsang.", sourceObjectiveStatus = "unverified-source-field" }
quests[51218] = { id = 51218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht zugestelltes Paket", description = "<Der geplünderte Wagen hat schon bessere Tage gesehen. Es ist nur noch eine Kiste übrig, die von verschüttetem Getreide bedeckt ist. Die Kiste ist an Marie Fürbittshafen in Mühlsteinweiler adressiert.>", sourceObjective = "Liefert das Paket bei Marie Fürbittshafen ab.", completion = "Ohhh, meine Güte! Ihr habt meinen verlorenen Tee gefunden. Ich danke Euch ganz herzlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[51220] = { id = 51220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwimmlektionen", description = "Obgleich Ai'twen sehr mächtig ist, stellt die Venture Company dennoch eine Bedrohung für ihn dar. Ihr müsst für mich über Ai'twen und Toki wachen, während Ihr Euer großes Abenteuer fortsetzt.\n\nSchaltet die Seeschrauber der Venture Company aus, die in den Wassern lauern, zu denen Ihr reist.", sourceObjective = "Eliminiert 6 Seeschrauber.", completion = "Ihr habt den Schurken der Venture Company einen gewaltigen Rückschlag beschert und Ai'twen beschützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[51221] = { id = 51221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reaktion erforderlich", sourceObjective = "Vernichtet Lithia Knauser.", completion = "Ihr habt uns mit Euren Heldentaten wertvolle Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[51222] = { id = 51222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermintes Gelände", description = "Während eines Besuchs auf Pandaria sah ich, wie ein Bewohner von Halbhügel einen Ho-zen-Angriff zurückschlug, indem er ihre eigenen Ausscheidungen auf sie zurückwarf.\n\nDie Ho-zen waren einfach nicht darauf vorbereitet, dass ihre eigenen Waffen gegen sie gerichtet werden könnten. So eine ähnliche Strategie möchte ich hier anwenden. Wir werden Seeminen der Venture Co. einsammeln und diese gegen die Eindringlinge einsetzen. \n\nIhr befestigt Seile an jeder Mine, und Ai'twen und ich werden sie einholen.", sourceObjective = "Sammelt 10 Seeminen.", completion = "Ausgezeichnete Arbeit, {name}. Unser Plan entwickelt sich prächtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[51223] = { id = 51223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über Scherben laufen" }
quests[51224] = { id = 51224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profit und Aufklärung", description = "Das sollte eine Geheimoperation sein. Leider wollte unser Handelsprinz unbedingt mitkommen... mit dem lautesten und auffälligsten Fahrzeug, das die Horde je erschaffen hat.\n\nWenigstens seid Ihr mit von der Partie, {name}.\n\nAlso, machen wir uns auf den Weg. Wir wissen praktisch nichts über das Gebiet von Drustvar. Es wird Zeit, etwas Aufklärungsarbeit zu leisten.", sourceObjective = "Eskortiert Gallywix und Etrigg auf Gallywix' Kriegstrike.\n\nFalls Ihr von Gallywix und Etrigg getrennt werdet, könnt Ihr sie in Jederhafen wiederfinden.", progress = "Bringen wir es hinter uns.", completion = "Bei diesen Wäldern bekomme ich ein mulmiges Gefühl.\n\nWartet mal kurz... Was ist DAS?!", sourceObjectiveStatus = "unverified-source-field" }
quests[51225] = { id = 51225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beflügelter Schrecken" }
quests[51226] = { id = 51226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod aus zwei Richtungen", description = "Die übergroßen Eidechsen vom Strand sind plötzlich in Scharen ins Lager gestürmt.\n\nWir sind es ja gewohnt, jede Woche ein oder zwei von ihnen zu bekämpfen, aber jetzt scheint es, als sei ihre gesamte Brut das Kliff hinaufgestürmt. Ich frage mich, ob der Geruch von Blut sie angelockt hat.\n\nSie gefährden unsere verbleibenden Leute, also beseitigt sie!", sourceObjective = "Tötet 8 Salzzahnsaurolisken.", completion = "Immerhin ein Problem wäre beseitigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[51228] = { id = 51228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instantfleisch, verzehrfertig" }
quests[51229] = { id = 51229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errichtet einen Brückenkopf", description = "Ich werde nicht zulassen, dass Gefreiter Leonhard umsonst gestorben ist. Wir holen unsere Leute her und sichern diesen Ort, bevor diese... \"Sethrak\" sich entschließen zurückzukommen.\n\nHier, platziert dieses Banner an einem gut sichtbaren Ort, damit die Schiffsmannschaft weiß, dass es sicher ist. Die Plattform am Dock sollte diesen Zweck erfüllen.", sourceObjective = "Stellt das Allianzbanner auf und errichtet Eure Basis in Vol'dun.", completion = "Die Mannschaft schlägt unser Lager in Rekordzeit auf! Die Sicherung des Brückenkopfs war gute Arbeit.\n\nWas nun Unteroffizier Elkmar angeht...", sourceObjectiveStatus = "unverified-source-field" }
quests[51230] = { id = 51230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallverpflanzung", description = "Flussknospe is' echt wertvoll für uns. Sie hat nich' nur starke magische Kräfte, sondern ernährt auch viele der Tiere, die wir ausbild'n oder selbst ess'n.\n\nLeider ham die Bluttrolle 'ne Menge verfluchtes Blut in die Flüsse gekippt. Sie woll'n das vielleicht nich', aber wenn wir nich' bald was tun, könnte die Flussknospe durch die Verschmutzung aussterb'n.\n\nNehmt diese Handvoll Samen und pflanzt sie im Flussschlamm ein. Dafür zeig ich Euch, wie Ihr sie besser ernt'n könnt.", sourceObjective = "Pflanzt 10 Flussknospensamen im Flussschlamm.", completion = "Ich kann Euch nich' genug danken! Flussknospe is' lebenswichtig für die Zandalari un' die Natur hier. Jedenfalls hab ich gesagt, dass ich Euch was beibringe un' ich steh' zu meinem Wort.\n\nDie Flussknospe, die Ihr gepflückt habt, wirkt 'n bisschen schlapp. Wenn Ihr die Knollen pflückt, reißt sie nich' bloß vom Stängel. Stattdessen solltet Ihr sie erst dreh'n. Dann bleiben die Stängel zusammengedrückt un' kein Pflanzensaft kann auslaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51231] = { id = 51231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexophobie", description = "Seht Ihr die... die Gestalt da oben in den Dornenranken vor uns? Ist der... <Etrigg schaudert.>\n\nIst der Goblin... in den Baum eingewickelt?", sourceObjective = "Untersucht die Gestalt vor Euch und beschützt dann Etrigg und Gallywix.", completion = "Hab Euch doch GESAGT, ich hab ein mulmiges Gefühl bei dieser Sache...", sourceObjectiveStatus = "unverified-source-field" }
quests[51232] = { id = 51232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einhundert Trolle im Weg" }
quests[51233] = { id = 51233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffentlich keine Hexen in den Hügeln", description = "<Gallywix hat nach seinem traumatischen Erlebnis mit der bösen Hexe die Fassung verloren.>\n\nWisst Ihr, ähm... Ich glaube, wir sollten unseren Stützpunkt lieber anderswo errichten. Vielleicht oben in den Bergen? Ihr wisst schon, also... nicht hier, wo die Hexen sind?", sourceObjective = "Fahrt Etrigg und Gallywix zu den Bergen.", progress = "Ja, {name}?", completion = "Damit... damit kann ich arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[51234] = { id = 51234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Außenposten Krazzelfrazz", description = "Ich habe bereits eine Menge der Laufarbeit für die Errichtung unseres Stützpunkts erledigt. Jetzt müssen wir nur die ganze Instantbasistechnologie implementieren und wir können in Drustvar loslegen.\n\nWarum stellt Ihr die Basis nicht fertig? Ich versuche derweil, einige Wolftorradteile aufzutreiben.", sourceObjective = "Benutzt die Goblingeräte im Außenposten Krazzelfrazz, um Euren Stützpunkt in Drustvar zu errichten.", completion = "Na also. Das ist echt toll.\n\nUnd heh, seht mal! Hier sind ein paar frische Raketentrupps.", sourceObjectiveStatus = "unverified-source-field" }
quests[51238] = { id = 51238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlassen in den Höhlen" }
quests[51239] = { id = 51239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Anleitung" }
quests[51240] = { id = 51240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Ankermaul", description = "Tötet den verfluchten Hai, der meine Beine verschlungen hat! Und meine Mannschaft! Und mein Boot - mitsamt Anker!\n\nEr treibt sich im Meer herum, immer auf der Suche nach seiner nächsten Mahlzeit. Tötet ihn.\n\nIch hab Cesi Zündschnur eine Belohnung dafür überlassen.\n\n<Das Plakat wurde von einem \"Kapitän Schlackeblitz\" unterzeichnet.>", sourceObjective = "Tötet Ankermaul in den Gewässern bei Jederhafen.", completion = "Gut gemacht! Hier habt Ihr die Belohnung, die Schlackeblitz mir gegeben hat. Er wird sich freuen, dass der Hai fort ist, wenn er wieder in den Hafen einläuft.", sourceObjectiveStatus = "unverified-source-field" }
quests[51241] = { id = 51241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexenbären" }
quests[51243] = { id = 51243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nahrungskette durchbrechen", description = "Die zusätzlich'n Flussknospen, die Ihr gepflanzt habt, ham geholfen, aber es reicht nich'. Ein paar der Meerestiere hier fress'n die Flussknospen, bevor sie reif sin'. Diese Pflanzen müss'n keimen, oder wir riskier'n, dass wir alle verlier'n.\n\nDie größte Gruppe, die junge Flussknospen fressen, sin' Hechtbuntbarsche. Wenn wir woll'n, dass die Flussknospe das überlebt, müssen wir sie dezimier'n.\n\nTut das un' ich bring Euch alles bei, was ich über die Flussknospe weiß.", sourceObjective = "Tötet 12 unersättliche Hechtbuntbarsche.", completion = "Danke, dass Ihr diese Fische getötet habt! Mir tut das nich' leid, denn sie wär'n verhungert, wenn keine Flussknospen mehr da sin', also hatten sie wenigstens 'nen schnellen Tod.\n\nDas Geheimnis für Flussknospen ist, dass im Wurzelwerk zusätzliche Knollen steck'n. Also zieht die Pflanze gleichmäßig und fest am Stängel raus.", sourceObjectiveStatus = "unverified-source-field" }
quests[51244] = { id = 51244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis in der Tiefe", description = "War gute Arbeit, Ateena zu töt'n un' dieses... was auch immer das für 'n Konstrukt war, in das... was auch immer dieses Ding is'... runterzuschmeiß'n.\n\nMeine Späher ham Titanenhüter Hezrel auf dem Marsch zum sogenannten Altar der Fäulnis geseh'n.\n\nJetzt, wo wir das Konstrukt beseitigt ham, sollt'n wir da runterflieg'n un' uns mal anschau'n, was Hezrel so macht.\n\nDas sollt'n wir beide erledig'n, die Prinzessin hat in der Stadt zu tun.", sourceObjective = "Findet Titanenhüter Hezrel im Altar der Fäulnis.", completion = "Keine Zeit zu verlieren. Bereich voraus zeigt deutliche Anzeichen von Verderbnis durch G'huun.\n\nScanner deuten auf Verderbnis durch Leck in Eindämmungsanlage für G'huun hin.\n\nMuss voranschreiten und Leck schließen. Funktion kann nicht autonom erfüllt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[51245] = { id = 51245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin Holzfäller und mir geht's gut" }
quests[51246] = { id = 51246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehörige Abwrackung", description = "Ich kann kaum glauben, dass jemand das Schiffsunglück überstanden hat. Der Befehl lautet zu gewährleisten, dass mögliche Überlebende keine Stellung sichern können.\n\nAber es gab viel mehr von ihnen, als erwartet. Also müssen wir ihre Zahl dezimieren.\n\nUnd? Worauf wartet Ihr noch? Eine persönliche Einladung?", sourceObjective = "Tötet 10 Schiffbrüchige der 7. Legion.", completion = "Hier wimmelt es geradezu von Allianz. Wir haben getan, was wir konnten. Ich muss nach Verstärkung schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[51247] = { id = 51247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was sie bei sich trugen", description = "Wir müssen mehr über diese Seeleute erfahren, bevor wir Bericht erstatten.\n\nBestenfalls würden wir in ihr Lager einfallen, aber mit so vielen kann unsere kleine Gruppe es nicht aufnehmen. Zum Glück für uns konzentrieren sie sich mehr auf ihre Bergungsaktion als auf ihre Sicherheit. Seht, ob Ihr etwas über ihre Anführer herausfinden könnt, die dort plündern.", sourceObjective = "Beschafft Informationen von der Allianz.", progress = "Was habt Ihr herausgefunden?", completion = "Informationen ergeben sich nicht immer nur durch die offensichtlichsten Dinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[51248] = { id = 51248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Produktive Plagegeister", description = "Dieser Dschungel ist üppiger Lebensraum für die verschiedensten Kreaturen und Kleintiere. Zu dumm, dass wir uns hier mit Allianztreibholz herumschlagen müssen.\n\nAber ich hab da, glaube ich, eine ziemlich geniale Idee. Zwei Wörter: giftige Insekten.\n\nZuerst brauche ich eine Auswahl an Insekten... krabbelnde und fliegende. Nur so kann ich sicher sein, dass unsere Tests auch gründlich genug sind.", sourceObjective = "Sammelt 5 Käfer.", completion = "Die sind genau richtig!", sourceObjectiveStatus = "unverified-source-field" }
quests[51249] = { id = 51249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krabbenfestmahl", description = "Die Verlass'nen hatt'n keine Nahrung bei sich. Ich halt's für möglich, dass die Kannibalen sind, oder vielleicht müss'n die auch nix ess'n!\n\nTeekay un' ich werd'n hier drauß'n verhungern! {name}, wenn's nich' zu viel verlangt is', könnt Ihr uns was zu ess'n bring'n?\n\nVielleicht 'n paar frische Krabb'n?", sourceObjective = "Sammelt 7 Stücke Krabbenfleisch von den modrigen Sechsfüßern.", progress = "Mein Magen knurrt jetzt schon.", completion = "Das reicht vollkommen. Jetzt brauchen wir nur noch ein bisschen Butter. Und vielleicht etwas Zitrone.", sourceObjectiveStatus = "unverified-source-field" }
quests[51250] = { id = 51250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht einen Abflug!" }
quests[51251] = { id = 51251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kellerbewohner", description = "Seit dem viel zu frühen Tod der lieben, süßen Liesel, möge ihre Seele in Frieden ruhen, haben diese Schädlinge sich wie verrückt vermehrt.\n\nNeuerdings krabbeln riesige Spinnen aus dem Keller der südlichen Mühle.\n\nNiemand hat es bisher geschafft, dort hinunterzugehen, weil jeder Angst hat, in Netze eingewickelt und bei lebendigem Leibe gefressen zu werden!\n\nWürde es Euch etwas ausmachen, ein paar Arachniden zu zerquetschen und so viel Seide wie möglich zu sammeln?", sourceObjective = "Sammelt 8 Stücke Spinnenseide von Kellerhuschern.", progress = "Wenn doch nur Liesel noch hier wäre...", completion = "Jetzt, da die Spinnen zerquetscht wurden, können wir alle wieder ruhiger schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51252] = { id = 51252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kiros Wüstenblume" }
quests[51278] = { id = 51278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren und vergessen", description = "Wir haben die Verdorbenheit hautnah miterlebt, die von meinen früheren Brüdern Besitz ergriffen hat. Es ist Zeit, dem ein Ende zu bereiten.\n\nDer vor uns liegende Weg wimmelt zweifellos vor Lord Sturmsangs Kultisten und deren seelenveränderten Elementaren. Ich werde ihre Seelen mit der Totenglocke absorbieren, wenn sie fallen, wie Ihr es einst getan habt.\n\nDennoch, es wird keine Befreiung für diese Unholde geben... dieses Mal nicht. Wir brauchen sie, um die letzte Tür zum Schrein aufbrechen.", sourceObjective = "Füllt die Totenglocke mit Seelen.", progress = "Diese Last müssen wir tragen, aber ich bin froh, dass wir sie nicht allein tragen müssen.", completion = "Trauert nicht um die Gefallenen. Wir tun, was getan werden muss, um unser Volk zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[51279] = { id = 51279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazmanikultisten", description = "Die Gerüchte über die Bluttrolle aus Boralus passen nicht zu den Briefen, die wir von Hauptmann Conrad erhalten.\n\nZum Handeln gewillt? Bereit, mit uns gegen die Horde vorzugehen? Sie wollen uns ihre Magie beibringen?\n\nUnsinn.\n\nMan sollte sich nur mit diesen bösen Trollen beschäftigen, wenn man sie gerade töten will.", sourceObjective = "Tötet 15 Nazmanitrolle in Koramar.", completion = "Kennt Ihr dieses Gefühl, dass irgendetwas nicht stimmt, aber Ihr einfach nicht dahinterkommt? Das ist so belebend!", sourceObjectiveStatus = "unverified-source-field" }
quests[51280] = { id = 51280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opfergaben für G'huun", description = "Ich hab diese Kultisten mit beiden guten Augen im Blick behalten.\n\nIhre großen Gefäße da sehen ziemlich wichtig aus.\n\nHab mal eins geöffnet und es hat mir einen eisigen Schauer über den Rücken gejagt, aber es befand sich nichts von Wert darin.\n\nWenn es sich nicht zu stehlen lohnt, lohnt es sich nur noch zum Zertrümmern.", sourceObjective = "Zerstört 8 Opfergaben für G'huun in Zul'Nazman.", completion = "In diesem verfluchten Dschungel scheint es nicht viel von Wert zu geben. Warum hat Hauptmann Conrad nur gedacht, dass es sich lohnen könnte, mit ihnen zu handeln?", sourceObjectiveStatus = "unverified-source-field" }
quests[51281] = { id = 51281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Nazman", description = "Ich weiß nicht so richtig, was ich von diesem Harry halten soll. Aber ich gewöhne mich langsam an ihn. Hat irre Ideen über die Blutelfen, aber er ist nicht übel.\n\nWorüber haben wir gerade geredet? Ach ja.\n\nHauptmann Conrad. Harry hat gesagt, der Hauptmann wäre nach Zul'Nazman gegangen, um mit den Bluttrollen zu verhandeln. Das scheint... eine weniger gute Planung zu sein.\n\nGehen wir mal und schauen, was man dort entdecken kann, ja?", sourceObjective = "Trefft Brann Bronzebart bei Zul'Nazman in Nazmir.", completion = "So langsam glaube ich, dass wir nur noch einen Leichnam finden werden. Ich kann mir nicht mehr wirklich vorstellen, dass unser berühmter Hauptmann Conrad noch am Leben ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[51282] = { id = 51282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptmann Conrad", description = "Sieht so aus, als wären ein paar Wachen bei dieser Hütte postiert. Wenn ich raten müsste, würde ich Hauptmann Conrad da drin vermuten.\n\nDoch irgendetwas stimmt hier einfach nicht. Geht Ihr doch schon voraus. Ich bleibe hier, falls etwas schiefgeht.\n\nIch gebe Euch Rückendeckung, {name}.", sourceObjective = "Trefft Euch mit Hauptmann Conrad bei Tul'vor in Nazmir.", completion = "Ich habe mich schon gefragt, wann Ihr mich finden würdet. Ich muss zugeben, dass ich gar nicht so sehr in Gefangenschaft bin, wie Ihr vermutlich denkt. Eigentlich ist es eher andersherum.", sourceObjectiveStatus = "unverified-source-field" }
quests[51283] = { id = 51283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Westen", description = "Aufklärer berichten, dass die Horde Vorstöße in die Wüste von Vol'dun vorgenommen hat.\n\nWir dürfen nicht zulassen, dass die Horde dort unkontrolliert weiterarbeitet, also bereiten wir eine Expedition vor, die eine Stellung errichten soll.\n\n{name}, es würde mich sehr freuen, wenn Ihr uns begleitet, schließlich habt Ihr mehr erreicht und erfahren als die meisten unserer Soldaten. Eure Hilfe könnte für den Erfolg der Mission unentbehrlich sein.\n\nSchließt Eure Angelegenheiten hier am Hafen ab und meldet Euch bei Großadmiralin Jes-Tereth. Wir setzen Segel, sobald Ihr bereit seid.", sourceObjective = "Sprecht mit Großadmiralin Jes-Tereth und reist nach Vol'dun.", completion = "Ich hoffe, die Reise hat Euch nicht seekrank gemacht, {name}. Unsere Mission fängt gerade erst an.", sourceObjectiveStatus = "unverified-source-field" }
quests[51284] = { id = 51284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falkenjagd" }
quests[51285] = { id = 51285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fressattacke" }
quests[51286] = { id = 51286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhindert die Evakuierung", description = "Das ist eine einzige Katastrophe. Die Informationen, die Ihr gesammelt habt, scheinen darauf hinzudeuten, dass sie bereits Stellungen auf dieser Insel haben und diese hier nur eine davon ist.\n\nSie haben ein Boot und wir müssen sie aufhalten. Hier ist etwas Zephyrium. Schiebt ihnen das auf ihrem Boot unter und sabotiert ihre Hoffnung auf Flucht. Wenn möglich, tötet den Käpt'n, der die Evakuierung leitet.", sourceObjective = "Haltet die Evakuierung der Allianz auf.", progress = "Ich hoffe, Ihr habt gute Neuigkeiten für mich. Ausnahmsweise mal.", completion = "Endlich läuft mal etwas so, wie es soll. Wir haben ihre Flucht für den Moment verhindert.", sourceObjectiveStatus = "unverified-source-field" }
quests[51287] = { id = 51287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: Versiegelte Vorräte" }
quests[51296] = { id = 51296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: Der Stolz des Aufsehers" }
quests[51297] = { id = 51297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: Küstengrundstück" }
quests[51302] = { id = 51302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tiefenpfuhl: Versiegeln von G'huuns Verderbnis", description = "Starker Austritt von G'huuns Verderbnis in der Nähe. Uns umgebende Substanz deutet auf G'huuns Verderbnis hin. Name der Substanz: Tiefenfäule.\n\nErste Scans deuten auf riesige Monstrosität aus Tiefenfäule im Tiefenpfuhl hin. Setzt weitere Verderbnis in Nazmir frei.\n\nEntfesselte Monstrosität muss vernichtet werden, um G'huuns Verderbnis einzudämmen.\n\nFunktion klar. Nach innen vorrücken.", sourceObjective = "Begebt Euch in den Tiefenpfuhl und besiegt die entfesselte Monstrosität.", completion = "Hezrel is' tot? So 'ne Schande, war 'n nützliches Ding.\n\nAber gut, dass wir das Monster da drin los sin'... Ich fürchte nur, dass das noch nich' alles war.\n\nWir müss'n noch das Konstrukt ausschalt'n, dass wir runtergeschoss'n ham... Hoffentlich find'n wir 'nen Weg, um G'huun eingesperrt zu halt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51305] = { id = 51305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glibberwolken" }
quests[51308] = { id = 51308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stützpunkt in Zuldazar", description = "König Wrynn gab uns Befehl, unsere besten Leute zu entsenden, um einen Stützpunkt in Zandalar zu etablieren. Damit seid Ihr gemeint.\n\nGlücklicherweise gibt es mehrere Stellen, an denen wir unser Lager aufschlagen können.\n\nBleibt hier. Dann gehen wir den Schlachtplan durch.", sourceObjective = "Hört Euch Kommandant Wyrmbanns Schlachtplan an und sprecht dann mit Großadmiralin Jes-Tereth, um zu Talanjis Tadel in Zuldazar zu reisen.", completion = "Verstärkung aus Kul Tiras? Perfekt. Ich war gerade dabei, eine weitere Hinrichtung zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[51309] = { id = 51309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine von Ragnaros", description = "Da meine Schamanen immer noch in ihren Beförderungsmitteln festsitzen, ist ein wichtiger Bestandteil unseres bevorstehenden Rituals immer noch zwischen den Vorräten verstreut.\n\nIch kann nur hoffen, dass die Horde nichts davon an sich genommen hat. Sie sind selten und wertvoll...\n\nWenn Ihr irgendwelche leuchtenden Objekte da draußen seht, sammelt sie ein. Sie sind unglaublich wertvoll.", sourceObjective = "Bergt 9 Stücke Schlacke der Feuerlande am Strand von Xibala.", progress = "Ich hatte keine Angst, dass sie kaputt sein könnten. So ein bisschen Feuer würde diesen Steinchen niemals schaden.", completion = "Ein paar Brandmale hier und da, aber nichts Außergewöhnliches. Die sind genau richtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[51310] = { id = 51310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuber der verlorenen Ernte", description = "Ich könnte hier ein wenig Hilfe brauchen!\n\nIch war bei der Ernte und dachte an nichts Böses, als diese großen Blödiane auf ihren Wölfen kamen und das Dorf in Brand steckten! Glücklicherweise war ich gerade dabei, einen Getreidesack auszuliefern, sonst hätten sie mich vermutlich eingefangen und zur Strecke gebracht!\n\nIch lass mir nicht gefallen, dass diese Orcs und ihre Köter meine Felder verwüsten oder meine Ernte fressen.\n\nWas denkt Ihr, <mein Freund/meine Liebe>? Würdet Ihr einem Bauern helfen, ein paar Räuber von seinem Land zu vertreiben?", sourceObjective = "Tötet 6 orcische Räuber.", completion = "Ha, das wird sie lehren, nicht mit ihren Kläffern anzukommen und unser Getreide zu stehlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[51311] = { id = 51311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energie spendendes Extrakt" }
quests[51312] = { id = 51312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aromatischer Bestäuber", description = "Beim Sammeln der Pollen habt Ihr ein totes Insekt entdeckt, das komplett von Pollen bedeckt ist. Ihr wisst, dass diese kleine Kreatur das Geheimnis für schnellere Pollensammlung in sich trägt. Ihr kommt jedoch einfach nicht dahinter.\n\nVielleicht hätte Derick eine Idee.", sourceObjective = "Bringt die tote, pollenbedeckte Biene zu Derick Segler.\n\nBereitgestellter Gegenstand:", completion = "Oh, hui. Ja, dieser Winzling ist wahrlich von Pollen bedeckt. Da kommt mir eine Idee... aber die wird Euch womöglich nicht gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51313] = { id = 51313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von den Besten lernen", description = "Ihr wollt erfahren, warum diese Bienen so gut darin sind, Pollen zu sammeln, aber wenn Ihr Euch nähert, schwärmen sie um Euch herum.\n\nDieses Problem lässt sich mit ein wenig Alchemie beheben. Ich habe zufällig einen Trank, der den Trinkenden in eine Pflanze verwandelt.\n\nAlso, das geht so: Ihr geht dort raus und trinkt den Trank, dann seht Ihr selbst, wie genau die Bienen das machen. Nachdem der Trank nachgelassen hat, sagt Ihr mir, was passiert ist.\n\nOh und fragt ja nicht, warum ich diesen Trank bei mir habe.", sourceObjective = "Trinkt Dericks Trank und gestattet den Bienen, Eure Pollen zu sammeln.", completion = "Faszinierend! Das klingt, als würden sie ihre Körper nutzen, um die Blütenöffnung zu blockieren und dann mit den Flügeln die Pollen aufzuwirbeln.\n\nDa die Pollen in den Blumen gefangen sind, haben sie keine andere Möglichkeit, als an den Bienen kleben zu bleiben.\n\nHm, wenn Ihr wieder einen Sirenendorn findet, bedeckt die Blume fast ganz mit Eurer Hand und pustet sanft hinein. Damit könnt Ihr die Methode der Bienen nachahmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51314] = { id = 51314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn um das Korn", description = "Wir müssen so viel wie möglich retten.\n\nDieses Tal ist die Kornkammer von Kul Tiras. Damit nähren wir die Einwohner, die Miliz, die Armee, einfach alle! Vielleicht habt Ihr vom berühmten Sauerteigbrot aus Kul Tiras gehört? Passt super zu Würstchen.\n\nAber darum geht es jetzt nicht, die verfluchte Horde hält uns von der Ernte ab! Glücklicherweise arbeiten die Golems pausenlos und packen weiter das Getreide ab.\n\nIhr müsst nur raus zu den Feldern gehen und so viele Säcke wie möglich mitbringen. Natürlich bezahle ich Euch für die Mühe.", sourceObjective = "Sammelt 8 Getreidesäcke.", progress = "Wir brauchen dieses Getreide!", completion = "Die Ernte ist dieses Jahr gut ausgefallen. Unsere Leute werden gut essen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51315] = { id = 51315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Flatterlinge" }
quests[51316] = { id = 51316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaziergang im Spinnennetz" }
quests[51317] = { id = 51317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzsteine klopfen" }
quests[51318] = { id = 51318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf das Boot" }
quests[51319] = { id = 51319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Aufstieg", description = "Hinter diesem Tor befinden sich Lord Sturmsang... und unsere Erlösung. Offenbar hat er es gut versiegelt, um Zeit zu gewinnen, damit er sein widerwärtiges Ritual, oder was uns da erwartet, beenden kann.\n\nEntlasst die Seelen aus der Totenglocke, wenn Ihr so weit seid. Ich werde sie in die Versiegelung leiten, die das Tor verschlossen hält.\n\nDanach suchen wir nach Sturmsang und bereiten all dem ein für alle Mal ein Ende.", sourceObjective = "Öffnet das Gewittertor.", progress = "Ganz gleich, was jenseits dieses Tores liegt, wir werden es gemeinsam angehen.", completion = "Ich dachte, dieser Moment würde niemals kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51320] = { id = 51320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegeltes Schicksal", description = "Voraus sind drei Zauberschutze, die drohen, uns den Zugang zum Schrein zu verwehren. Wir nennen sie Zorn, Glanz und Stolz der Gezeitenmutter.\n\nDen Legenden nach waren die Zauberschutze Geschenke des Meeres. Sie schützten einst unsere Flaggschiffe vor selbst den wütendsten Stürmen. Seit wir uns hier niedergelassen haben, werden sie eingesetzt, um den Schrein des Sturms zu beschützen.\n\nOffenbar hat Lord Sturmsang ihre Macht gegen uns gerichtet. Ich kann sogar von hier aus die Energie spüren, die von ihnen ausgeht und seine Truppen vor unserer Magie schützt.\n\nWir müssen sie vernichten.", sourceObjective = "Zerstört den Zorn der Gezeitenmutter, den Glanz der Gezeitenmutter und den Stolz der Gezeitenmutter.", progress = "Solange die Zauberschutze halten, werden wir Lord Sturmsangs Macht nichts entgegenzusetzen haben.", completion = "Ich spüre jetzt schon, wie die Macht der Zauberschutze schwindet. Das ist unsere Chance, zuzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51322] = { id = 51322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flügel und Stacheln" }
quests[51330] = { id = 51330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerstandsfähige Samenkörner" }
quests[51331] = { id = 51331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maulwurfmachenschaften", description = "Der Feind hat anscheinend unseren Plan erraten. Während wir unsere Verfeinerungsmethoden für Azerit entwickelt haben, haben die Goblins wohl dasselbe gemacht.\n\nKeine fünf Minuten, nachdem wir uns hier niedergelassen hatten, tauchte die Horde auf, um unsere Fortschritte zu bremsen.\n\nWir haben einige wichtige Schamanen, die ungeduldig in den Maulwurfmaschinen auf dem Strand dort warten.\n\nIhr könnt den Schlüssel nehmen und den Weg freimachen, damit sie sicher ihren Bestimmungsort erreichen.", sourceObjective = "Befreit 4 Erdbrecher der Dunkeleisenzwerge aus den Maulwurfmaschinen in Xibala.", completion = "Wenn sie nicht in Maulwurfmaschinen schmoren wollten, hätten sie sich einen anderen Beruf aussuchen sollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[51332] = { id = 51332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise über das Meer", description = "Ihr wollt also einen Stützpunkt in Drustvar errichten. Handelsprinz Gallywix wird Euch bei dieser Mission unterstützen.\n\nIch weiß, eine merkwürdige Entscheidung, aber mir wurde berichtet, dass es in Drustvar Azerit gibt, und der Handelsprinz hat darauf bestanden.", sourceObjective = "Meldet Euch bei Handelsprinz Gallywix in Zuldazar.", completion = "Hey, {name}. Wart Ihr schon mal in Drustvar?\n\nWir gehen nach Drustvar.", sourceObjectiveStatus = "unverified-source-field" }
quests[51333] = { id = 51333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anker lichten!" }
quests[51335] = { id = 51335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kekse mit Milch", sourceObjective = "Genießt Maries frischgebackene Kekse und Milch.", completion = "Nun, was haltet Ihr davon, {name}? Die sind echt klasse, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[51339] = { id = 51339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federweißer", description = "Die Venture Company verunreinigt unser klares Wasser mit giftigem Öl.\n\nMein Volk ist stark und wird das überstehen, bis die Zeit gekommen ist, um zurückzuschlagen. Die Kreaturen mit zarterer Haut können jedoch nicht so lange warten. Wir müssen jetzt handeln und sie vor dieser Gefahr bewahren.\n\nSammelt alle öligen Sandschnabelpfeifer, derer Ihr habhaft werden könnt, und säubert sie. Rasch, bevor es zu spät ist.", sourceObjective = "Säubert 8 ölige Sandschnabelpfeifer.", completion = "Diese Etappensiege sind die Grundlage für die Niederlage der Venture Company.", sourceObjectiveStatus = "unverified-source-field" }
quests[51340] = { id = 51340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drustvar voraus!", description = "Azerit liegt in der Luft, {name}. Könnt Ihr es riechen?\n\nUnter Drustvar, ganz weit drüben in Kul Tiras, liegt angeblich ein riesiges Azeritflöz. Azerit bedeutet Profit und Profit bedeutet, diesen Krieg gegen die Allianz zu gewinnen... was noch mehr Profit bedeutet.\n\nWir müssen an dieses Azerit herankommen!\n\nMeldet Euch bei Etrigg und Segelriss, damit wir bald aufbrechen können. Zeit ist Geld!", sourceObjective = "Sprecht mit Etrigg und Schreckensadmiralin Segelriss.", completion = "Da sind wir. Zeit, nachzusehen, was die Allianz so treibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[51341] = { id = 51341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tochter der See", description = "Sie lassen uns nicht näher an die Festung heran. Wir müssen von hier aus laufen.\n\nDie Rückkehr nach Boralus hat Gefühle aufgewühlt, von denen ich glaubte, ich hätte sie hinter mir gelassen... Erinnerungen, die im Laufe der Jahre geglättet wurden wie Steine von der Flut.\n\nJetzt fühlt sich alles wieder so frisch an.\n\nIch weiß nicht, wie das hier enden wird... nur, dass wir es versuchen müssen.", sourceObjective = "Begleitet Jaina Prachtmeer zu einer Audienz bei Katherine Prachtmeer.", completion = "Ich hoffe, Ihr habt ein angenehmes Schläfchen gehalten. Ihr werdet Eure Kraft brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51342] = { id = 51342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Stromgarde" }
quests[51343] = { id = 51343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwimmunterricht", description = "Seit Jahrtausenden durchstreifen wir die Tiefen von Azeroth, aber ein Landwandler hat uns noch nie begleitet. Um uns zu helfen, müsst Ihr lernen, so wie wir durchs Wasser zu reisen.\n\nWenn sie gleichzeitig gelesen werden, werden die drei Schriftrollen der See Euch die Energien verleihen, unter Wasser reisen und überleben zu können, wie wir es tun.\n\nBringt mir die Schriftrolle der harmonischen Flossen, der endlosen Fluten und des anmutigen Atems.", sourceObjective = "Sammelt die drei Schriftrollen.", progress = "Ihr müsst die Schriftrollen der harmonischen Flossen, der endlosen Fluten und des anmutigen Atems sammeln.", completion = "So ist es gut. Genau wie wir werdet Ihr jetzt eins mit dem Meer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[51344] = { id = 51344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtige Angelegenheiten", description = "Ihr müsst nach Zuldazar zurückkehren. Prinzessin Talanjis Volk braucht unbedingt Hilfe.\n\nJetzt, da Ihr das Herz habt, könnt Ihr Azerit aus allerhand Quellen absorbieren.\n\nBenutzt die Teleportplattform hinter Euch, um nach Zuldazar zurückzukehren. Ich werde sie abschalten, wenn Ihr fertig seid... Ist ja nicht nötig, dass Leute wie Nathanos hierherkommen.\n\nDenkt nur immer daran: Ihr habt das Herz von Azeroth um den Hals hängen. Was immer auch passiert... wir müssen den Planeten retten.", sourceObjective = "Benutzt die Teleportplattform, um nach Zuldazar zurückzukehren.", completion = "Gut, Ihr seid wieder da. Es gilt, keine Zeit zu verlier'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[51349] = { id = 51349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrengebunden", description = "Unteroffizier Elkmar ist ein Ehrenmann und würde niemals seine Leute zurücklassen. Doch irgendwann wird ihn diese Einstellung noch das Leben kosten.\n\nWir wissen nicht einmal, welchen Bedrohungen wir uns in diesem Land gegenübersehen. Und ganz sicher haben wir nicht die Mittel, nach einem vermissten Gefreiten zu suchen.\n\nIch will, dass Ihr ihm nachgeht und ihn mit allen Mitteln davon überzeugt, dieses sinnlose Unterfangen aufzugeben und ins Lager zurückzukehren. Als man ihn das letzte Mal sah, lief er nach Südosten. An Eurer Stelle würde ich dort mit meiner Suche beginnen.", sourceObjective = "Findet Unteroffizier Elkmar in Vol'dun.", completion = "Wyrmbann hat Euch hinter mir hergeschickt, ja? Nun, er wird warten müssen.\n\nDieses Ding weiß, wo der Gefreite James hingebracht wurde!", sourceObjectiveStatus = "unverified-source-field" }
quests[51350] = { id = 51350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerwartete Hilfe", description = "Ich habe diese Sethrak verfolgt, da sah ich, dass der hier neben dem Weg zum Sterben zurückgelassen wurde. Ich glaube, er ist anders als die anderen. Sieht so aus, als ob er von ihnen übel zugerichtet wurde.\n\nIch habe mit ihm Kontakt aufgenommen und bevor er bewusstlos wurde, sagte er, er wüsste, wo man unseren Mann hinbringt!\n\nWir müssen herausfinden, was dieses Ding weiß!\n\nIch muss eine Salbe für seine Wunden herstellen. Hier in der Nähe habe ich eine Kaktusart gesehen, die man gut als Grundlage dafür verwenden kann.", sourceObjective = "Pflückt 8 Kaktusfeigenwurzeln in der Knochensplitterschlucht.", progress = "Habt Ihr den Kaktus für die Salbe?", completion = "Die sind genau richtig!", sourceObjectiveStatus = "unverified-source-field" }
quests[51351] = { id = 51351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftige Stacheln", description = "Es überrascht mich, dass dieses Schlangenwesen noch lebt und sogar noch sprechen kann. Seht Euch das an!\n\n<Elkmar hält einen nadeldünnen Stachel hoch.>\n\nDer stammt möglicherweise von einem dieser riesigen Insekten unten in der Schlucht. Ich wette meine Streifen, dass der giftig ist.\n\nMan sagt ja gemeinhin, dass alles, was tötet, auch heilen kann.\n\nHolt mir noch ein paar dieser Stacheln. Ich wette, wenn ich sie mit der Kaktussalbe vermische, werden wir ein gutes Gegengift erhalten, mit dem wir seine Wunden behandeln können.", sourceObjective = "Sammelt 8 Salzrückenstacheln in der Knochensplitterschlucht.", progress = "Habt Ihr die Stacheln für mich?", completion = "Genau, was wir brauchen! Ich hoffe, Ihr seid nicht auch noch gestochen worden.", sourceObjectiveStatus = "unverified-source-field" }
quests[51352] = { id = 51352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Feuer spielt man nicht", description = "Diese Verbrecher von der Venture Co. zünden sogar das von ihnen geförderte Öl an, in der Hoffnung, uns aus diesem Land zu vertreiben.\n\nIhr Plan hat nur einen Fehler: Wenn eine große Welle jede Fackel auslöscht, können sie ihr Öl nicht mehr anzünden. Ihr könnt unsere große Welle sein!\n\nLöscht alle Flammen hier aus und wir werden heute siegreich sein.", sourceObjective = "Eliminiert 10 Feuerteufel der Venture Co. und 2 Öler der Venture Co.", completion = "Der Krieg hat gerade erst begonnen, aber das war ein großartiger erster Sieg!", sourceObjectiveStatus = "unverified-source-field" }
quests[51353] = { id = 51353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ai'twens Höhle", description = "Toki hat eine Strategie erforscht, die historisch gesehen hieb- und stichfest ist. Um allerdings die Venture Company zu besiegen, müssen wir Ai'twen in der Ruhewasserblase aufwecken.\n\nSucht Loroja in Ai'twens Höhle auf und wir beginnen mit dem Vorgang.", sourceObjective = "Sucht Loroja in Ai'twens Höhle.", completion = "Eure Anwesenheit hier kann nur eins bedeuten. Ai'twens Hilfe wird benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[51354] = { id = 51354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn in der Flasche", description = "Diese Stacheleber sind zäher als üblich und ich glaube, ich weiß, warum.\n\nSie tragen irgendwelche Fläschchen mit einer widerlichen, orangenen Flüssigkeit bei sich. Sie stürzen sie hinunter und erhalten unglaubliche Stärke und Ausdauer.\n\nIch wette, wenn es uns gelingt, etwas davon zu beschaffen, kann Hobbs ein Gegenmittel zusammenbrauen, oder wie immer das heißt, was Alchemisten tun. So oder so, wenn man ihnen ihre Stärketränke nimmt, wird man sich hier wesentlich leichter bewegen können!", sourceObjective = "Sammelt 10 stinkende Proben.", sourceObjectiveStatus = "unverified-source-field" }
quests[51355] = { id = 51355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimster Fisch", description = "<Danielle Anglers in Mechagon interessiert sich bestimmt für diesen Fisch.>", sourceObjective = "Bringt den Fisch zu Danielle Anglers in Mechagon.\n\nBereitgestellter Gegenstand:", completion = "Wo habt Ihr diesen Fisch gefunden? Er eröffnet uns viele neue Möglichkeiten der Erforschung von Fischen!\n\nEs ist nur eine kleine Anpassung nötig, dann kann ich einen rudimentären Köder modifizieren und damit mehr Fische als je zuvor anlocken!\n\nNatürlich könnte das stattdessen auch mehr Fischer anlocken.", sourceObjectiveStatus = "unverified-source-field" }
quests[51356] = { id = 51356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schwester Lilias", description = "Die Kronsteigwache sucht einen fähigen Soldaten, der eine Bedrohung in Korlach beseitigen kann.\n\nEine Hexe namens Schwester Lilias wird gesucht, weil sie große Teile der Stadtbevölkerung gefoltert und getötet hat. Ihr Ableben wäre ein großer Segen für ganz Drustvar.\n\nWeist ihren Kopf vor, um Eure Belohnung zu erhalten.", sourceObjective = "Besorgt Schwester Lilias' Kopf von Schwester Lilias in Korlach.", completion = "Ah, die Hexe ist tot. Gut.\n\nHier ist Eure versprochene Belohnung. Weiter so, Inquisitor.", sourceObjectiveStatus = "unverified-source-field" }
quests[51357] = { id = 51357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewaffnet und bereit", description = "Ihr müsst etwas Besonderes sein, wenn die Sethrak Euch nicht auf der Stelle getötet haben.\n\nEntweder das, oder Ihr bringt einen guten Preis auf dem Sklavenmarkt.\n\nAber keine Sorge. Wir kommen hier schon raus.\n\nIch habe einen Wagen am Eingang, aber keine Waffe, mit der ich kämpfen könnte.\n\nZum Glück scheinen die Sethrak ja eine Menge davon zu haben.", sourceObjective = "Wählt eine Waffe für Nisha.", progress = "Mir ist es gleich, wofür Ihr Euch entscheidet, aber wir sollten uns beeilen.", completion = "Sie mit ihren eigenen Waffen bekämpfen. Das gefällt mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[51358] = { id = 51358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Greifenentführer", description = "Eine Warnung an alle Greifbesitzer!\n\nLasst Eure gefiederten Begleiter nicht aus den Augen. Wir haben einige Berichte erhalten, dass in dieser Gegend Greifen mitten in der Nacht gestohlen wurden.\n\nWenn jemand diese Diebe aufspüren und ausschalten kann, erhält er eine Belohnung.", sourceObjective = "Tötet Lindel den Langfinger und den stillen Boris.", completion = "Ich habe gehört, die vermissten Greifen wären zurückgekehrt!\n\nIch schätze, das haben wir Euch zu verdanken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[51359] = { id = 51359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragment der Feuerlande", description = "Die Gerüchte über Eure Fähigkeiten wirkten übertrieben, aber wie es scheint, seid Ihr doch recht kompetent, nicht wahr?\n\nIch hab Euch unterschätzt, {name}. Dafür entschuldige ich mich. Sagt es nicht Thaelin weiter.\n\nDie Komponenten für das Ritual sind jetzt vorbereitet. Ihr müsst nur noch die Schlacke der Feuerlande zu dem instabilen Magma hinzufügen und ein großes Wesen der Feuerlande wird unserem Ruf Folge leisten.\n\nIhr übernehmt die Kontrolle darüber, werdet nahezu unbesiegbar und könnt dann die Goblinbedrohung auslöschen.", sourceObjective = "Stabilisiert das instabile Magma und benutzt dann den Magmaelementar, um 200 Bilgewassergoblins zu besiegen.", progress = "Meine Schamanen werden immer besser, oder? Nach den ersten paar Beschwörungen waren wir in einen heißen Kampf verwickelt.", completion = "Ah haha haaaaaaaaaaaa! Ich muss zugeben, ich bin ein wenig neidisch, dass ich Euch zuerst eine Runde damit habe drehen lassen. Die Goblins haben Euch nicht mal kommen sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[51360] = { id = 51360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesige Ankerkrautkapsel", description = "Bei Eurer ganzen Sammelei seid Ihr bisher noch nie auf eine Ankerkrautkapsel dieser Größe gestoßen. Was auch immer der Grund für ihr außergewöhnliches Wachstum sein mag, es ließe sich sicher viel daraus lernen.\n\nIhr müsst an Derick denken und fragt Euch, ob in dem Buch, das Ihr vorhin beschafft habt, vielleicht etwas darüber stehen könnte.", sourceObjective = "Bringt die riesige Ankerkrautkapsel zu Derick Segler.\n\nBereitgestellter Gegenstand:", completion = "Au weia... Die scheint auf jeden Fall größer als normal zu sein, aber selbst in dem Buch steht nichts über eine riesige Samenkapsel. Das könnte Schlimmes bedeuten...", sourceObjectiveStatus = "unverified-source-field" }
quests[51361] = { id = 51361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Ankerkrautkapseln", description = "Jeder in Kul Tiras weiß, dass das Ankerkraut eine Plage ist, die von Händlern hier eingeschleppt wurde.\n\nIn diesem Klima gedeiht es besonders gut und gräbt den anderen Pflanzen die Nährstoffe ab. Wir müssen daher seine Ausbreitung verhindern. Leider verfügt es über eine sehr starke magische Essenz. Wir können es also nicht einfach vernichten.\n\nWenn es jedoch mutiert ist und jetzt noch mehr Samen verbreiten kann, müssen wir es vielleicht doch noch restlos beseitigen.\n\nSchnappt Euch die größten Samenkapseln, die Ihr finden könnt. Wir müssen herausfinden, ob das eine einmalige Mutation ist. Ich werde diese hier zerschneiden und versuchen, mehr herauszufinden.", sourceObjective = "Erntet 9 reife Ankerkrautkapseln von Ankerkraut.", progress = "Wenn das Ankerkraut mutiert, müssen wir es vielleicht in diesem Land ausrotten. Habt Ihr die anderen Samenkapseln zum Vergleich?", completion = "Die hier sehen alle normal groß aus, was meinen Verdacht bestätigt.\n\nAls ich diese riesige Samenkapsel zerlegt habe, sind mir Glassplitter aufgefallen und ich bemerkte einen alchemistischen Geruch in der Luft. Das klingt verrückt, aber ich glaube, dass irgendeinem Abenteurer ein Riesenwuchselixier heruntergefallen ist. Die Phiole ist zerborsten und diese Pflanze hat alles aufgesaugt.\n\nDurch die Größe der Riesenkapsel ist mir außerdem aufgefallen, dass die vermeintlich dicken Wände tatsächlich sehr dünn sind, dafür aber weitere Samenkapseln aufweisen! Ihr könnt die Kapsel schälen und noch mehr Samen erhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[51364] = { id = 51364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein explosiver Abgang", sourceObjective = "Findet Nishas Wagen und bringt Euch damit in Sicherheit.", completion = "Das ist die Trollfrau, mit der Ihr hergeflogen seid, nicht wahr? Für den Moment ist sie noch am Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[51365] = { id = 51365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kulturelle Bedeutung", description = "Mir ist aufgefallen, dass sich Euer Geschick im Sammeln von Pflanzen verbessert hat. Mir ist aber auch aufgefallen, dass ihr die Blüten und Blätter einfach nur als Ware behandelt. Die Pflanzenwelt dieser Insel hat eine lange Geschichte und ist von großer Bedeutung für unsere Kultur.\n\nNehmt diesen Meeresstängel und fragt einige Männer und Frauen in der Stadt, was er ihnen bedeutet. Tut mir den Gefallen, dann soll es sich auch für Euch lohnen.", sourceObjective = "Erfahrt die Bedeutung der Meeresstängel von den Menschen in Boralus.", completion = "Meeresstängel haben eine einzigartige magische Eigenschaft, durch die der Stängel die Blüte mit Wasser versorgt, selbst wenn man sie abschneidet.\n\nSeeleute geben ihren Liebsten eine Blüte und behalten den Stängel. Falls sie dann über Bord gehen, tötet das Salzwasser die Blüte. Was Ihr da in den Händen habt, ist kein einfacher Stecken, sondern steht für das Leben eines Familienmitglieds.\n\nWas Eure Lektion angeht: Im Gegensatz zu den meisten magischen Pflanzen enthält hier der Stängel die meiste magische Essenz, nicht etwa die Blätter oder Blüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[51366] = { id = 51366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilende Salbe", description = "Das Gegenmittel ist bereit.\n\nEs stinkt wie der Tod und schmeckt noch schlimmer, aber es sollte stark genug sein. Hoffen wir, dass es nicht schon zu spät ist, um etwas damit auszurichten.\n\nHier, tragt die Salbe auf seine Wunden auf. Sie sollte mehr oder weniger sofort wirken.", sourceObjective = "Verabreicht Vorrik das Gegengift.", completion = "Ich spüre, wie das Leben in meine Glieder zurückkehrt. Danke, Fremder!\n\nWir haben leider keine Zeit, uns näher bekannt zu machen, da die Treulosen Euren Freund gefangen halten.\n\nKeine Sorge, meine Leute werden Euch im Gegenzug für Eure Freundlichkeit mir gegenüber gerne helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51367] = { id = 51367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Tobender Erdwächter", description = "Seid vorsichtig, wenn Ihr nach Angelpunkt reist!\n\nEine riesige Erdkreatur ist auf einem der Hügel erschienen und bedroht alle, die sich in ihre Nähe wagen.\n\nAbenteurer, die diesen Erdwächter ausschalten, werden fürstlich belohnt.", sourceObjective = "Tötet den tobenden Erdwächter westlich des Anwesens der Norwinsens.", completion = "Ihr habt den Klagegeist besiegt! Hervorragend! Gute Arbeit wie immer, mein Lieber!", sourceObjectiveStatus = "unverified-source-field" }
quests[51368] = { id = 51368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Die Hornisse", description = "Jetzt reicht's. Ich setze ein Kopfgeld auf diese verfluchte Hornisse aus.\n\nJedes Mal, wenn ich schön altmodisch ein bisschen mit bloßen Händen fischen will, ist dieses verfluchte Vieh hinter mir her.\n\nKann mal jemand dieses Insekt ausschalten?!", sourceObjective = "Tötet die Hornisse.", completion = "Die Hornisse ist tot! Ihr macht Euch gut als Ungeziefervernichter.\n\nIch will nicht von einem Krabbeltier umgebracht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[51369] = { id = 51369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde auf Abwegen", description = "Ich habe ein Wesen wie Euren Freund hier gesehen. Wir wurden beide von meinen skrupellosen Brüdern, den Treulosen, gefangen gehalten.\n\nBevor man sich meiner entledigt hat, habe ich ihm etwas gegeben, das er beschützen sollte. Etwas sehr Kostbares. Ich würde Euren Freund daher also auch gerne wohlbehalten zurück sehen.\n\nMein Volk wird Euch helfen. Kommt, ich werde meinen Pterrordax rufen, damit er uns hinbringt. Zusammen werden wir herausfinden, wo Euer Soldatenfreund hingebracht wurde.", sourceObjective = "Fliegt zum Sanktum der Ergebenen.", completion = "Oh nein! Die Treulosen greifen den Tempel an!", sourceObjectiveStatus = "unverified-source-field" }
quests[51370] = { id = 51370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnungen sind knapp" }
quests[51371] = { id = 51371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schmackhafte Opfergabe", description = "Ai'twen hat während der großen Säuberung der Tintengrotte viele Tortollaner gerettet. Als Lohn für seinen Dienst ruht er hier in dieser Ruheblase. Wir brauchen eine schmackhafte Opfergabe, um ihn zurück in unsere Welt zu locken.\n\nDer Seetang, der draußen wächst, ist Ai'twens Lieblingsmahlzeit. Sein salziger Geschmack wird Ai'twen sicher dazu bringen, aus der Blase in unsere Welt zu kommen. Sammelt ihn von den Kreaturen außerhalb dieser Höhle und am Riff, wo er wild wächst.", sourceObjective = "Sammelt 50 Seetang.", progress = "Sucht nach dem Seetang draußen und bei Salzpanzermakruras.", completion = "Eine hervorragende Opfergabe. Lasst uns jetzt sehen, ob sie ausreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[51373] = { id = 51373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überall Ohren" }
quests[51374] = { id = 51374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlose Gorillakriegsführung" }
quests[51376] = { id = 51376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerer Bauch unterrichtet nicht gern", description = "Ich würde Euch ja gerne unterrichten, aber es fällt mir gerade so schwer, mich zu konzentrieren. Ich habe den ganzen Tag nichts gegessen, also kann ich an gar nichts anderes denken.\n\nWenn mir jedoch ein hilfsbereiter Abenteurer zufällig ein paar Spurschnapper aus dem Meer hinter mir angeln würde, wäre ich demjenigen etwas schuldig. Vielleicht sogar etwas Wertvolles, wie etwa Ratschläge zum effektiven Pflücken des berüchtigten Winterkuss.\n\nWenn Euch nicht zum Angeln zumute ist, könnt Ihr auch im Auktionshaus welche kaufen. Das ist mir völlig gleich.", sourceObjective = "Sammelt 7 Spurschnapper für Xun Xun Duftblüte. Spurschnapper können aus dem Meer geangelt oder im Auktionshaus gekauft werden.", progress = "Oh, habt Ihr etwas für mich?", completion = "Ihr habt mir frischen Fisch gebracht? Was für eine wunderbare Überraschung! Jetzt kann ich mich endlich ganz auf den Unterricht eines lernwilligen Schülers konzentrieren.\n\nWer versuchen will, einen Winterkuss zu pflücken, der muss vor allem eines wissen: Wird die Pflanze vor dem Abernten Wärme ausgesetzt, kann dies dazu führen, dass die Blüte verwelkt.\n\nUm das zu verhindern, müsst Ihr Eure Hände direkt vor dem Pflücken in den Schnee graben. So werden sie kalt genug, dass Ihr sogar problemlos ein paar zusätzliche Blütenblätter ergattern könnt.\n\nViel Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[51377] = { id = 51377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel von Sethraliss: Ökologische Forschung" }
quests[51378] = { id = 51378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel von Sethraliss: Bazar des Bizarren" }
quests[51379] = { id = 51379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel von Sethraliss: Ein Weg durch die Strömungen" }
quests[51380] = { id = 51380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Franko", description = "Oh, schön! Ihr seid immer noch hier!\n\nIch habe gehört, Ihr habt Euch mit Franko angefreundet. Über ihn zu sprechen, lässt mich immer noch an damals denken, als wir zusammengearbeitet haben.\n\nWarum geht Ihr nicht zu ihm, wenn Ihr Zeit habt? Fragt ihn, ob er Euch noch was beibringen kann. Er erinnert sich bestimmt noch an mehr, sofern Ihr noch mehr erfahren möchtet.\n\nUnd sagt ihm, dass ich gern mit ihm über eine erneute Zusammenarbeit sprechen würde, wenn er sein Leben wieder in Ordnung gebracht hat.", sourceObjective = "Sprecht mit Franko dem Säufer.", completion = "Mirte schickt Euch?\n\nMoment... meine frühere Geschäftspartnerin?", sourceObjectiveStatus = "unverified-source-field" }
quests[51384] = { id = 51384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Rüstmeister Ssylis", description = "Wagt Euch nicht zu weit in die Bucht, wenn Ihr es nicht auf einen Kampf abgesehen habt!\n\nEin paar Bilgeratten haben sich in einer Höhle in der Nähe eingenistet und lehnen keine Herausforderung ab.\n\nSolange man sich fernhält, tun sie niemandem weh. Aber sollte sich doch jemand um den Anführer kümmern, kriegt derjenige eine Belohnung.", sourceObjective = "Tötet Rüstmeister Ssylis in der Krakenfluchbucht.", completion = "Jawohl, Ihr habt den Saurok erwischt.\n\nDie Bilgeratten sollten bald von hier verschwunden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[51385] = { id = 51385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stachelvorrat" }
quests[51386] = { id = 51386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegreich im Kampf", description = "Wir haben alles, was wir brauchen, um dieser Venture Company einen herben Schlag zu versetzen.\n\nUnser Plan ist gut durchdacht, wir sind gut vorbereitet und werden sie überraschen.\n\nWir werden auf Ai'twen reiten und mit ihren eigenen Waffen Chaos auf sie herabregnen lassen.", sourceObjective = "Reitet auf Ai'twen und vernichtet die Streitkräfte der Venture Company.", completion = "Dieser Sieg wird noch jahrtausendelang in aller Munde sein. Aber die Venture Company ist ein zäher Feind. Ich bin mir sicher, dass wir sie wiedersehen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[51388] = { id = 51388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Befall aufhalten" }
quests[51389] = { id = 51389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch", description = "Seht, die Jungs da sind in einer brenzligen Lage, aber wir müssen unsere Mission im Auge behalten. Wir müssen den Gefreiten James retten!\n\nIch habe einige Käfige im Lager der Schlangen gesehen, die den Tempel belagern. Wenn wir James irgendwo finden, dann da!", sourceObjective = "Findet den Gefreiten James und befreit ihn aus seiner Gefangenschaft.", completion = "Ich kann nicht glauben, dass Ihr und der Uffz Euch solche Mühen gemacht habt, um mich zu retten! Ich... Ich bin ganz sprachlos... Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[51390] = { id = 51390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Die blutigen Halsabschneider", description = "Wegen zahlreicher und niederträchtiger Vergehen gegen die Lordadmiralin: Schmuggel, Fälschung, Seefahrt unter falscher Flagge, Plünderei, Wilderei, Raub, Brandschatzung, mutwillige Beschädigung, Amtsanmaßung durch Ausgabe als Offiziere der Marine von Kul Tiras, Brandstiftung, Entführung, Folter, Piraterie, Meineid, Diebstahl und Ansichnahme mehrerer Metlieferungen.\n\nAuf die Köpfe der blutigen Halsabschneider ist eine Belohnung ausgesetzt, die bei einem Beweis ihres Ablebens in Gänze ausgezahlt wird.", sourceObjective = "Tötet die blutigen Halsabschneider in der Nähe von Falkenforst.", completion = "Ihr habt diese vermaledeiten Gesetzlosen endlich erwischt? Gute Arbeit! Meine Leute haben hier schon genug Ärger, ohne sich mit Briganten herumschlagen zu müssen.\n\nNehmt diese Belohnung und meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[51391] = { id = 51391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Treulosen die Zähne ziehen", description = "Habt Ihr sie gesehen, als wir im Anflug waren? Die Treulosen belagern den Tempel!\n\nIch weiß, dass wir uns gerade erst kennengelernt haben, doch ich muss Euch erneut um Hilfe bitten. Bitte helft uns, ihre Reihen zu lichten!", sourceObjective = "Tötet 12 treulose Angreifer in den Tempelhöfen.", completion = "Ich habe schon gehört, wie Ihr die Treulosen in die Flucht geschlagen habt!\n\nIch danke Euch im Namen meines Volks.", sourceObjectiveStatus = "unverified-source-field" }
quests[51394] = { id = 51394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Belagerung durchbrechen", description = "Dies ist nicht das erste Mal, dass die Treulosen uns angreifen, und sicher auch nicht das letzte Mal. Aber wir müssen den Tempel beschützen!\n\nTut, was in Eurer Macht steht, um ihre Belagerungswerkzeuge zu zerstören und sie zurückzuschlagen.", sourceObjective = "Haltet den Angriff der Treulosen auf das Sanktum der Ergebenen auf.", completion = "Die Treulosen werden ihre Belagerung niemals aufgeben, aber Eure Bemühungen haben uns etwas Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[51395] = { id = 51395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlüssel der Hüter", description = "Schön, dass wir Euren Gefährten unversehrt zurückhaben.\n\nAber was noch wichtiger ist: Lasst uns mal sehen, ob er noch meinen Stein in seinen Taschen versteckt hat.", sourceObjective = "Sprecht mit dem Gefreiten James und erschließt die Bedeutung von Vorriks Stein.", completion = "Die Treulosen werden ihre Belagerung niemals aufgeben, aber Eure Bemühungen haben uns etwas Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[51397] = { id = 51397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angst vor dem Bohrer", description = "<Der Bohrer vorne an der Maschine ist in gutem Zustand.>\n\n<Scheint perfekt geeignet, um für gefährliche Arbeitsbedingungen zu sorgen.>", sourceObjective = "Benutzt die Goblinbergbaumaschine, um das Ausgrabungslager zu stören.", sourceObjectiveStatus = "unverified-source-field" }
quests[51398] = { id = 51398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungewöhnlicher Lehrmeister", description = "He, {name}. Ich glaube, Ihr seid bereit, Euch in feindliches Gebiet vorzuwagen.\n\nWeit weg, in den Wüsten Vol'duns auf dem Kontinent Zandalar, wächst eine Pflanze, die Akundas Biss heißt. Mich kriegt Ihr da um kein Geld der Welt hin, und in den Büchern, die ich gelesen habe, wird die Pflanze kaum erwähnt, aber es ist nicht alles verloren.\n\nIch kenne einen Kräuterkundler, der dort in der Wüste lebt und diese Pflanze studiert. Findet ihn, dann kann er Euch das eine oder andere beibringen. Ach, und ich muss Euch warnen...\n\nEr ist ein wenig... exzentrisch.", sourceObjective = "Findet Patu in Vol'dun.", completion = "Ihr sucht nach Wissen über Akundas Biss? Eine prachtvolle Pflanze, aber überraschend empfindlich, wenn man die harsche Umgebung bedenkt. Dort überleben wirklich nur die Stärksten...\n\nHmmm... Ja, Ihr scheint geeignet zu sein. Wenn Ihr mir bei meiner Arbeit helft, werde ich mein Wissen mit Euch teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51399] = { id = 51399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Üble Ernte", description = "Ihr seid weit gereist, um Wissen zu finden, und habt stattdessen mich gefunden. Ich würde jedoch gerne wissen, wie weit Ihr dafür noch gehen würdet. Ich werde Euch lehren, wenn Ihr zuerst etwas für mich tut.\n\nEisen wird durch Eisen geschärft, wie man so schön sagt, und auch in diesem Fall stärken widrige Umstände die Saat.\n\nZieht los und findet Samenkörner, die von den Wildtieren verschlungen und unversehrt der Erde zurückgegeben wurden.\n\nNur diese Samen werden stark genug sein, um in den Wüstensanden von Vol'dun zu überleben.", sourceObjective = "Sammelt 12 verdaute Samenkörner von Akundas Biss.", progress = "Konntet Ihr die Samenkörner besorgen?", completion = "Hmm... Das sieht mir nach einer guten Ernte aus. Ihre Widerstandsfähigkeit hat eine stille Würde an sich.\n\nDoch Würde allein reicht nicht. Sie dürfen nicht einfach nur still sein, sie müssen vor Donner erbeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[51401] = { id = 51401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitermachen", description = "Lasst uns sofort nach Brennadam gehen. Wir müssen Bruder Pike finden und der ganzen Sache auf den Grund gehen, bevor alles noch schlimmer wird.\n\nDiese Straße sollte uns direkt in die Stadt führen. Brennadam ist der bestbesuchte Markt diesseits von Boralus, also sollten dort mehr als genug Leute sein, die uns helfen können, Pike zu finden.\n\nIch bin so weit, wenn Ihr es seid.", sourceObjective = "Trefft Euch mit Taelia in Brennadam.", completion = "Das sieht nach weiterem Ärger aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[51402] = { id = 51402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht erstatten", description = "Ich kann nicht fassen, wo wir hier hineingeraten sind. Schlüsselsteine, C'Thraxxi und sogar ein Bürgerkrieg unter den Schlangenwesen!\n\nIch weiß nur, dass Wyrmbann einen kompletten Bericht haben wollen wird, und wenn ich eins noch weniger leiden kann als unfähige Gefreite, die sich gefangen nehmen lassen, dann ist es Papierkram.\n\nGehen wir.", sourceObjective = "Meldet Euch bei Hochkommandant Halford Wyrmbann.", completion = "<Wyrmbann hört sich Euren Bericht an.>\n\nDie Neuigkeiten bezüglich dieses C'Thraxxi machen mir Sorgen, aber Ihr habt gut daran getan, Euch mit den Einheimischen anzufreunden. Das ist vermutlich nicht das letzte Mal, dass wir auf sie angewiesen sind.\n\nGute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[51403] = { id = 51403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gebot des Sprechers", description = "Die Seele der Welt ist vorerst sicher. Ich kann Azeroth wieder hören, obwohl ihre Stimme immer noch schwach ist.\n\nDie Elementare auf der Oberfläche haben sich wieder beruhigt. Das Herz von Azeroth hat diesen Ort wieder stabilisiert, obwohl es nur über einen Bruchteil seiner Macht verfügt hat.\n\nKehrt nach Sturmwind zurück. Setzt Eure Verbündeten über das, was hier geschehen ist, ins Bild. Erinnert sie daran, dass es egal ist, was mit der Horde passiert. Das Wichtigste ist, dass unsere Welt gerettet wird.\n\nWir sprechen uns bald wieder, {name}. Der Kampf um Azeroth hat gerade erst begonnen.", sourceObjective = "Kehrt nach Sturmwind zurück.", completion = "<Wyrmbann hört sich Eure Geschichte an.>\n\nDas Herz von Azeroth... wirklich ein sehr mächtiges Artefakt. Ich danke dem Licht, das Ihr da wart und Magni helfen konntet.\n\nAber ich fürchte, ich habe schlechte Neuigkeiten, {name}. In Eurer Abwesenheit hat die Horde einen hinterhältigen Angriff auf Sturmwind durchgeführt.\n\nIch habe eine Nachricht von König Anduin für Euch. Ihr müsst ihn sofort in der Festung treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51404] = { id = 51404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie es weitergeht", description = "Nachdem Ihr Akundas Biss so oft gespürt habt, lässt Euch die statische Elektrizität die Haare zu Berge stehen, als Ihr eine intakte Blitzschlagkapsel in den Händen haltet. Euch fällt auf, dass Ihr die Kapsel entfernen konntet, ohne sie zu entladen, indem Ihr sie in ihre eigenen Blätter gewickelt habt.\n\nWenn Ihr diese Technik weiterentwickeln könntet, wäre es deutlich weniger gefährlich, diese Pflanze zu ernten, und Ihr würdet dabei mehr einwandfreies Material erhalten.Ihr erlernt:", sourceObjective = "Erntet 10 Akundas Biss, ohne einen Schock zu erleiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[51405] = { id = 51405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis in der Bucht" }
quests[51406] = { id = 51406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd des Lords" }
quests[51407] = { id = 51407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet ihre Worte", description = "Dieses Portal bringt Euch schnell zum Außenposten zurück.\n\nZeigt dort Akru die Befehle.\n\nSie weiß viel und wird die darin enthaltene Wahrheit erkennen können.", sourceObjective = "Bringt die Befehle aus Nazjatar zu Akru am Sucheraußenposten.", progress = "Ah. Deyon hat recht, ich weiß viel. Was habt Ihr denn da?", completion = "Ja... ja... Ich sehe schon. Das sind in der Tat schlimme Worte, mein Kind.", sourceObjectiveStatus = "unverified-source-field" }
quests[51408] = { id = 51408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zur Natur", description = "Erledigt eine weitere Aufgabe, dann schenke ich Euch das Wissen, das Ihr sucht. Eure Samenkörner sind stark, aber sie brauchen Zeit, bis sie bereit sind zu wachsen.\n\nIn der Wüste muss man jedoch immer auf alles gefasst sein. Der Setzling ist reif genug, um allein zu leben, doch er ist zart. Er braucht den trockenen Wüstenwind, um Reibungselektrizität aufzubauen und beißen zu können. Bis dahin ist er wehrlos wie ein Grashalm.\n\nPflanzt ihn in den Wüstensand in der Nähe des gefallenen Tiers südlich des Salzbeckens und beschützt ihn, bis er sich selbst verteidigen kann.", sourceObjective = "Pflanzt den Setzling von Akundas Biss und beschützt ihn, bis er statisch aufgeladen ist.", progress = "Habt Ihr den Setzling schon gepflanzt? Hat er Wurzeln geschlagen?", completion = "Eure Mühen haben entscheidend dazu beigetragen, das Gleichgewicht in diesem Land zu erhalten.\n\nJetzt werde ich Euch mit dem Wissen belohnen, nach dem Ihr strebt... Aber vorher, wenn Ihr Euch der Pflanze nähert, was macht Ihr dann?\n\n<Patu nickt, als Ihr Euren aktuellen Wissensstand über das Sammeln von Akundas Biss darlegt.>\n\nHmmm... Ihr kennt den Wert der Blätter dieser Pflanze offenbar nicht. Die Kapsel entlädt sich bei Berührung, was die Blätter abtötet, wenn sie immer noch festsitzen. Erntet diese also zuerst und Eure Ausbeute wird größer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[51411] = { id = 51411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritbergbau" }
quests[51412] = { id = 51412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritermächtigung" }
quests[51415] = { id = 51415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritwahn" }
quests[51418] = { id = 51418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xibala", description = "{name}! Wie läuft es hier?\n\nOh. Himmel. Hier wimmelt es ja von Soldaten der Horde. Und Zandalaritrollen. Und Maschinen gibt es fast gar keine.\n\nWir sollten DEFINITIV mit den Dunkeleisenzwergen nach Xibala zurückkehren. Der perfekte Ort für unseren Stützpunkt!", sourceObjective = "Benutzt das Ruderboot in Talanjis Tadel, um nach Xibala zu reisen.", completion = "Ihr seid also {name}, der {class}, von dem Kelsey so viel hält? Euer Ruf eilt Euch voraus!", sourceObjectiveStatus = "unverified-source-field" }
quests[51421] = { id = 51421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potz Blitz", description = "Anscheinend ist es unserem hiesigen Schattenjäger gelungen, eine kleine Piratenschaluppe aufzutreiben.\n\nWir haben ihn zum Tiragardesund geschickt, um eine Stellung zu suchen, und anscheinend hat er einen Plan geschmiedet.\n\nTy'jin hat höchstpersönlich um Eure Hilfe gebeten. Lasst ihn nicht warten.", sourceObjective = "Begleitet Schattenjäger Ty'jin zum Tiragardesund.", completion = "Willkomm' in Tiragarde, Boss. Bereit zum Parley?", sourceObjectiveStatus = "unverified-source-field" }
quests[51422] = { id = 51422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritwahn" }
quests[51425] = { id = 51425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am schönsten ist es zu Hause", description = "Ja, das Arathihochland ist ganz schön weitläufig, nicht wahr?\n\nIhr kommt vielleicht mal an einen Punkt, an dem Ihr rasch nach Stromgarde zurückkehren wollt.\n\nDürfte ich Euch dazu einen Vorschlag machen?", sourceObjective = "Sprecht mit Hauptmann Roderick Bräustein.", sourceObjectiveStatus = "unverified-source-field" }
quests[51426] = { id = 51426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Gerätschaften", description = "Vor einiger Zeit hat ein guter Freund von mir, der einen Tüftlerladen in Boralus hat, sämtliche Korrespondenz eingestellt. Angesichts der außenpolitischen Lage konnte ich bis vor Kurzem nicht nach ihm suchen.\n\nEs geht aber nicht nur um ihn. Anscheinend sind alle Gnome, die in der Stadt gelebt haben, spurlos verschwunden.\n\nIch habe beschlossen, meine Suche in diesen Ruinen zu beginnen, doch die Geräte hier sind völlig durchgedreht. Könntet Ihr eine gute magnetische Messung des Orts vornehmen?", sourceObjective = "Untersucht das Verrostete Gewölbe.", completion = "Die Daten sind faszinierend! Es wird eine Weile dauern, alles durchzugehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51427] = { id = 51427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich mag Schildkröten", sourceObjective = "Bietet Ai'twen die Opfergabe dar.", progress = "Wir haben Geduld. Wann immer Ihr bereit seid.", completion = "Eine hervorragende Opfergabe. Lasst uns jetzt sehen, ob sie ausreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[51428] = { id = 51428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritwunden" }
quests[51429] = { id = 51429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König Zwickizwack" }
quests[51430] = { id = 51430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgekehrte Tüftelei", description = "Die Späh-o-Bots hier wurden auf jeden Fall von Gnomen hergestellt. Wenn der Hersteller eine anständige Ausbildung genossen hat, sollten alle Maschinen eine Art Seriennummer aufweisen.\n\nUnd wenn darüber ordentliche Aufzeichnungen existieren, könnte ich diese Codes benutzen, um diesen Gnom zu finden.\n\nMeint Ihr, Ihr könntet mir ein paar bringen?", sourceObjective = "Sammelt 4 V-300-Seriennummernschilder.", progress = "Habt Ihr etwas Interessantes gefunden?", completion = "Ich werde die nach Eisenschmiede zurückschicken lassen. Dann werden wir ja sehen, ob sie etwas herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[51431] = { id = 51431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelengoliath" }
quests[51432] = { id = 51432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungewöhnlicher Lehrmeister", description = "Ihr habt Euch bis jetzt gut geschlag'n, {name}, aber Ihr habt noch so viel mehr zu lern'. Ich glaub, es is' Zeit, dass Ihr 'nen alten \"Freund\" kennenlernt.\n\nIch kenn niemand, der Euch besser was über Akundas Biss beibring'n könnte. Keiner weiß mehr über die Pflanze als er oder hat solch'n Respekt für sie.\n\nGeht nach Norden, über die Wüste von Vol'dun hinaus. Da findet Ihr 'nen Tortollaner, der Euch mehr über die Wüstenblume lehr'n wird.", sourceObjective = "Findet Patu in Vol'dun.", completion = "Ihr sucht nach Wissen über Akundas Biss? Eine prachtvolle Pflanze, aber überraschend empfindlich, wenn man die harsche Umgebung bedenkt. Dort überleben wirklich nur die Stärksten...\n\nHmmm... Ja, Ihr scheint geeignet zu sein. Wenn Ihr mir bei meiner Arbeit helft, werde ich mein Wissen mit Euch teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51433] = { id = 51433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matrone Morana" }
quests[51434] = { id = 51434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steingolem" }
quests[51435] = { id = 51435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modisches Säbelrasseln", description = "Ein Hauer nach'm anderen, Boss. Mit Piraten könnt Ihr nich' einfach so schwatz'n. Ihr braucht 'n ordentliches Freibeuterkostüm.\n\nSo wie Ihr rumlauft, macht Ihr nur Bekanntschaft mit den Säbeln von denen.\n\nZum Glück hab ich diese Kiste mit Piratenklamotten hier. Fragt mich nich' woher. Zieht Euch um und macht Euch bereit.", sourceObjective = "Zieht eine Piratenverkleidung aus der Kiste mit Piratentracht an.", progress = "Nehmt, was Ihr wollt, Boss. Die Kiste is' randvoll mit Klamott'n.", completion = "Beim Klabautermann, Boss! So könnt Ihr auf jedem Piratenschiff anheuern!", sourceObjectiveStatus = "unverified-source-field" }
quests[51436] = { id = 51436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parley mit Piraten", description = "Einige der Piraten sin' nich' zufried'n mit ihren Anführern.\n\nIch hab gehört, dass das die letzt'n wirklich freien Piraten sin'. Die andren haben sich von 'ner Lady namens Aschenwind kauf'n lass'n.\n\nIs' mir eigentlich egal, aber der Kapitän der Nebelfockfreibeuter wird auch bald dem Lockruf vom Gold erlieg'n.\n\nWir müss'n das verhindern und hier 'nen Stützpunkt aufbau'n.", sourceObjective = "Folgt Schattenjäger Ty'jin und trefft Euch mit dem Ersten Maat Ottkens.", completion = "Eure internen Streitereien kümmern mich nicht, {name}. Wenn Ihr meine Mannschaft rettet, werde ich Euch helfen, darauf könnt Ihr Euch verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51437] = { id = 51437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fassanstich", description = "Wie man eine Meuterei anzettelt? Lasst es so aussehen, als ob die Anführer absolut unfähig sind.\n\nWenn der Kapitän dann unsere Seelen den Aschenwinds verkaufen will, schlagen wir zu... aber es wird dreckig werden.\n\nIch sage es ja nur ungern... aber wir werden irgendetwas mit ihrem Gesöff anstellen müssen.\n\nDie Mannschaft wird dem Kapitän schneller an die Gurgel gehen, als Ihr \"rostiger Enterhaken\" sagen könnt.", sourceObjective = "Stecht 6 Fässer Grog an.", completion = "So habe ich das eigentlich nicht ge...\n\nWisst Ihr was? Gut so. Das wird funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[51438] = { id = 51438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Territorium markieren", description = "Das könnt 'n ziemlich guter Stützpunkt werd'n, <Scheff/Scheffin>!\n\nIch werd mit dem Aufbau'n helf'n, damit das 'ne richtig gute Basis wird.\n\nIch glaub, wir brauch'n ein paar Stacheln.\n\nMach'n wir die Sache offiziell.", sourceObjective = "Platziert das Hordenbanner im Raubhafen.", completion = "Hier wird sich's bald wie Zuhaus' anfühl'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[51439] = { id = 51439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonenkugelkoller", description = "Aufm Weg durch den Hafen is' mir was eingefall'n, Boss.\n\nSeht Ihr die groß'n Kerle mit ihren Kanonenkugeln?\n\nSammelt 'n paar von denen und bringt die dann zu mir. Ich glaub, ich kann damit was anfang'n.", sourceObjective = "Sammelt 3 Kanonenkugeln der Nebelfockfreibeuter von Kanonieren der Nebelfockfreibeuter.", progress = "Habt Ihr die Kanonenkugeln gekriegt?", completion = "Oh, die Goblins sin' voll scharf auf die Dinger, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[51440] = { id = 51440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Richtungswechsel", description = "Man hört im ganzen Hafen Stimmen des Widerspruchs, {name}.\n\nÜberall findet man murrende Piraten, die ihre Freiheit nicht aufgeben wollen!\n\nGerüchten zufolge gibt es noch andere Autoritätspersonen, deren Ziele mit meinen übereinstimmen.\n\nIch habe ein paar gefälschte Briefe in der Handschrift des Käpt'ns verfasst. Liefert sie aus... und seht, wer anbeißt.\n\nOder wer sich uns in den Weg stellt.", sourceObjective = "Überbringt die gefälschten Briefe Bootsfrau Tila, Rüstmeister Killian und Navigator Schwinn.", completion = "Ich hatte gehofft, Tila würde die Wahrheit erkennen. Tja, da kann man wohl nichts machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51441] = { id = 51441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versenkt!", description = "Unsre Gobliningenieure ham dran gearbeitet, 'n paar Kanonen für unsre Zwecke zu modifizier'n.\n\nDie Kanonenkugeln, die Ihr gesammelt habt, sin' dafür die perfekte Munition.\n\nIm Hafen mach'n sich Ruderboote fertig, um Beute zu Ottkens Feinden zu bring'n. Nehmt die Kanone un' versenkt sie, bevor sie abhau'n könn'.", sourceObjective = "Benutzt die goblingefertigte Handkanone, um 3 Ruderboote der Nebelfockfreibeuter zu versenken.", completion = "Jetz' hab'n wir 'ne richtige Meuterei!", sourceObjectiveStatus = "unverified-source-field" }
quests[51442] = { id = 51442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer ist hier der Käpt'n?", description = "Also gut, {name}... Es wird Zeit, mit der Meuterei Ernst zu machen.\n\nRhenik bereitet sich in seiner Höhle darauf vor, unsere Seelen an die Aschenwinds zu verkaufen!\n\nBesiegt ihn und Ihr könnt meinen Hafen benutzen, als wäre es Euer eigener.", sourceObjective = "Tötet Käpt'n Rhenik.", progress = "Ich kann nicht untätig zusehen, wie Rhenik unsere Freiheit verkauft.", completion = "Käpt'n Ottkens...\n\nDas klingt irgendwie nicht schlecht, meint Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[51443] = { id = 51443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Missionsrichtlinie", description = "{name}! Der Kriegshäuptling hat Euch mit einer äußerst geheimen Mission betraut.\n\nDie Zukunft der Horde steht auf dem Spiel.", sourceObjective = "Erfahrt Eure Mission von Kriegshäuptling Sylvanas Windläufer in Orgrimmar.", completion = "Die Dunkle Fürstin hat ihr Vertrauen in uns gelegt. Wir werden nicht versagen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[51444] = { id = 51444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritermächtigung" }
quests[51445] = { id = 51445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thros, die Verseuchten Lande", description = "Die Verseuchten Lande...\n\nWenn die Legenden wahr sind, werden wir dort Zeuge von unaussprechlichem Leid werden...\n\nAber wenn das der Preis ist, um meine Fehler wiedergutzumachen, bin ich mehr als bereit, diesen Weg zu gehen.\n\nWerdet Ihr mich begleiten, {class}?", sourceObjective = "Findet Jaina in Thros, den Verseuchten Landen.", completion = "Ich kann nicht in Worte fassen, wie dankbar ich Euch dafür bin, dass Ihr mir geholfen habt, meine Tochter zurückzubringen. Aber leider lässt uns diese Verräterin Aschenwind keine Zeit zum Feiern.\n\nWir müssen handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[51446] = { id = 51446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rendezvous mit Duftblüte", description = "Auf diesen Inseln habt Ihr wirklich viel seh'n un' viel lern' könn', aber Zandalar is' nich' der einzige Ort, an dem Ihr was lern' könnt. Ich hab von 'ner Blume gehört, die nich' auf den Inseln wachs'n kann.\n\nWenn Ihr mehr darüber erfahr'n wollt, braucht Ihr wen, der mehr weiß als ich. Ich weiß auch schon genau, wen Ihr da aufsuch'n müsst.\n\nIhr Name is' Xun Xun Duftblüte un' ich hab gehört, dass sie sich in der Nähe von Jederhafen niedergelass'n hat. Das is' drüb'n auf der Mensch'ninsel Drustvar.", sourceObjective = "Findet Xun Xun Duftblüte in Drustvar.", completion = "Oh, Ihr wollt erfahren, wie man Winterkuss richtig pflückt? Das trifft sich ja wirklich gut... für uns beide...", sourceObjectiveStatus = "unverified-source-field" }
quests[51447] = { id = 51447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aromatischer Bestäuber", description = "Beim Sammeln der Pollen habt Ihr eine tote Wespe entdeckt, die komplett von Pollen bedeckt ist. Ihr wisst, dass dieses Insekt das Geheimnis für schnellere Pollensammlung in sich trägt. Ihr kommt jedoch einfach nicht dahinter...\n\nVielleicht hätte Jahden eine Idee.", sourceObjective = "Bringt die tote pollenbedeckte Wespe zu Jahden Fla.\n\nBereitgestellter Gegenstand:", completion = "Ja, Ich kenn' diese Wespen. Sie sin' berüchtigt dafür, dass sie... Da kommt mir tatsächlich 'ne Idee... aber ob die Euch gefällt, bin ich mir nich' sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[51448] = { id = 51448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von den Besten lernen", description = "Ihr wollt erfahr'n, warum diese Wespen so gut darin sin', Pollen zu sammeln, aber wenn Ihr Euch nähert, schwärm'n sie aus und verteidig'n ihr Gebiet? Das is' sicher 'n Problem, aber ich weiß, wie Ihr das umgeh'n könnt.\n\nNehmt diesen Trank un' geht nach Vol'dun in den Stachelhain. Trinkt ihn, dann verwandelt Ihr Euch in 'ne Pflanze.\n\nAlso, das geht so: Ihr geht dort raus un' trinkt den Trank, dann seht Ihr selbst, wie genau die Wespen das mach'n. Nachdem der Trank nachgelass'n hat, sagt Ihr mir, was passiert is'.", sourceObjective = "Trinkt Jahdens Trank und gestattet den Wespen, Eure Pollen zu sammeln.", progress = "Schon zurück?", completion = "Es is' gut, dass Ihr das aus erster Hand erleb'n konntet. Klingt fast so, als hätt'n die ihre Flügel benutzt, um die Pollen aufzuwirbeln. Und weil sie so nah an der Blume war'n, musst'n die Pollen einfach an den Wespen häng'n bleib'n.\n\nHmm, wenn Ihr das nächste Mal 'nen Schwärma'dorn habt, probiert mal, Eure Hand fast vollständig über die Öffnung der Blüte zu leg'n und dann ma' sanft reinzupusten. Damit macht Ihr im Prinzip das Gleiche wie die Wespen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51450] = { id = 51450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritbergbau" }
quests[51451] = { id = 51451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerlich feuchte Blume", description = "Ihr sammelt weiter fleißig Pollen ein und nutzt die Technik, die Ihr von den Wespen gelernt habt. Als Ihr dann allerdings die Hand von der Blume wegzieht, seht Ihr trotzdem keine Pollen.\n\nIhr schaut genau im Wirbel der Blütenblätter nach, und obwohl es eine erwachsene Pflanze ist, seht Ihr überhaupt keine Pollen darin. Nach näherer Untersuchung bemerkt Ihr eine zähe Flüssigkeit in der Blume. Stammt sie von der Blume selbst?\n\nVorsichtig pflückt Ihr die Pflanze, was Euch einiges Unbehagen bereitet, um sie Jahden zu zeigen.", sourceObjective = "Bringt die widerlich feuchte Blume zu Jahden Fla.\n\nBereitgestellter Gegenstand:", completion = "Hmm... In dieser Blume sin' überhaupt keine Pollen mehr vorhand'n. Das wär die erste Pflanze, die sowas freiwillig macht. Das muss das Werk von 'ner andren Kreatur gewes'n sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[51452] = { id = 51452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollen auf die Hand", description = "Ich glaub, dass irgend'ne Kreatur die ganzen Pollen mit der Zunge aufgenomm' hat. Ich würde zwar gern wiss'n, was das für 'ne Kreatur is', aber es macht eigentlich auch kein' Unterschied.\n\nIch glaub, wir könn' versuch'n, das ohne selt'ne oder gefährliche Reagenzien nachzumach'n.\n\nWenn Ihr wieder ma' 'nen Sirenendorn findet, dann feuchtet einfach Euren Handschuh an, damit die Pollen dran kleben bleib'n. Ob mit Wasser, Wein oder Spucke... Das sollte egal sein.Ihr erlernt:", sourceObjective = "Sammelt 12 gehäufte Handvoll feuchter Pollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51453] = { id = 51453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein des Sturms: Sehet das reine Wasser" }
