quests[51462] = { id = 51462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallschirmjäger" }
quests[51463] = { id = 51463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung vom Himmel" }
quests[51464] = { id = 51464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Geiste dabei", description = "Wenn Ihr Euch rantraut, hab ich 'ne Aufgabe für Euch, die Euch lieg'n sollte.\n\nDie Geister in diesem Land schrei'n vor Qual. Sie woll'n in dieser Verfassung aber nich' mit mir red'n.\n\nIhr müsst mir frisches Sternmoos beschaff'n. Damit kann ich die Geister bind'n und beruhig'n. Sobald ich das geschafft hab, kann ich ihnen bei ihrem Problem helf'n.\n\nWenn Ihr das für mich macht, bring ich Euch bei, wie Ihr Sternmoos effektiver ernt'n könnt.", sourceObjective = "Sammelt 10 Stücke frisches Sternmoos.", progress = "Die Geister sind ruhelos. Habt Ihr schon frisches Sternmoos find'n könn'n?", completion = "Ihr habt gute Arbeit geleistet. Ich fang so schnell wie möglich mit dem Ritual an.\n\nIn der Zwischenzeit schuld ich Euch 'ne Lektion in Sach'n Sternmoosernte.\n\nDie Magie vom Sternmoos reagiert empfindlich auf Emotionen. Deswegen lass'n sich damit auch die Geister der Toten beruhig'n.\n\nWenn Ihr es ernt'n wollt, müsst Ihr mit klarem Kopf an Eure lieben Verstorbenen denk'n. Das Gefühl vom Verlust, die Ehrfurcht und die Freude, die sie Euch einst gebracht ham, werd'n verhindern, dass die Blüte welkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[51465] = { id = 51465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haufen Schrott", description = "He, Ihr da, Fremdling. Interesse an einem Exklusivbericht über die schärfste neue Entwicklung des Jahrhunderts?\n\nSie heißt Schreddermeister Mk1, und dieses Baby kann Eure Produktionskapazität bei der Herstellung von Rüstungen, Waffen oder anderen nützlichen Abenteurerutensilien verdreifachen, ach was, sogar verVIERfachen!\n\nHier, nehmt doch mal diese Hose und nutzt den Schreddermeister. Ihr werdet begeistert sein!", sourceObjective = "Benutzt den Schreddermeister Mk1 mit der zerschlissenen Hose.", progress = "Diese Maschine wird alles verändern.", completion = "Und einfach so, ratz, fatz, seid Ihr wieder am Start! All die Materialien, die bei der Herstellung des Objekts verwendet wurden, werden durch den Schreddermeister Mk1 wieder nutzbar.\n\nOkay, na gut. Nicht ALLE Materialien. Aber es ist immer noch besser, als alles zu verlieren, oder?\n\nOh, und achtet auf das Vorkommen von Explusom. Das ist ein magisches Material, das wir beim Wiederverwertungsprozess als Nebenprodukt entdeckt haben.\n\nEs ist ziemlich mächtig und entsteht nur, wenn man das gute Zeug verwertet.", sourceObjectiveStatus = "unverified-source-field" }
quests[51466] = { id = 51466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arvon der Verratene" }
quests[51467] = { id = 51467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyo'gi" }
quests[51468] = { id = 51468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenschwall" }
quests[51469] = { id = 51469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betti" }
quests[51472] = { id = 51472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebenserhaltung", description = "Die Dornsprecher haben mir zwar geholfen, doch sie haben auch mit ihren eigenen Problemen zu kämpfen.\n\nIch bin gekommen, um nach einem mächtigen Drachen zu suchen, der vor vielen Jahrhunderten im Kampf gefallen ist. Der schmelzende Schnee hat nun Vadekius' letzte Ruhestätte preisgegeben.\n\nMeine Königin hat mir den Auftrag gegeben, sicherzustellen, dass sein Körper niemals wiedererweckt und versklavt werden kann. Das dafür benötigte Ritual erfordert meine gesamte Aufmerksamkeit, und meine Druidenfreunde sind nicht kampftauglich.\n\nGebt mir Deckung, während ich dafür sorge, dass die Seele meines Vetters unbedroht vom Untod zwischen den Ästen von G'Hanir fliegen kann.", sourceObjective = "Beschützt Zallestrasza während sie das Ritual ausführt.", completion = "Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[51474] = { id = 51474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Feuer und Flamme geschmiedet", description = "Ihr habt mehr getan, als ich jemals von Euch hätte verlangen können, {name}. Ihr habt Eisenfeind unseren Feinden entrissen, ein Fragment des Geschmolzenen Kerns geborgen und in den Feuerlanden den Verräter in unseren Reihen gestellt.\n\nWürdet Ihr mir die Ehre erweisen, ein letztes Mal mit uns in die Schwarzfelstiefen zu gehen, während wir unseren hochheiligen Amboss reparieren?", sourceObjective = "Sprecht mit Moira an der Botschaft von Sturmwind, um in die Schwarzfelstiefen zu reisen und den Schwarzen Amboss zu reparieren.", progress = "Ihr habt uns wahrlich gerettet, {name}.", completion = "Wir sind Euch sehr dankbar, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[51475] = { id = 51475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Eskorte" }
quests[51478] = { id = 51478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistige Beruhigung", description = "Ich hab mit den Geistern gesproch'n. Die meisten war'n bereit, ihre Seelen zu offenbar'n, um die Lebenden um Hilfe anzufleh'n, weil sie von der bösartig'n Magie der Bluttrolle angegriff'n werd'n.\n\nEiner der Geister war aber noch wütender als alle andren. Er war extrem wütend, dass wir noch nix unternomm' ham und dass wir zugelass'n ham, dass es so weit komm' konnte.\n\nGeht nach Norden zum Gasthaus \"Geister mit Euch\" im Hafen un' erlöst diesen Geist von sei'm Leid. Dann werd ich mein ganzes Wissen über das Ernten von Sternmoos mit Euch teil'n.", sourceObjective = "Bringt den wütenden Geist zur Ruhe.", completion = "Ich schuld' Euch meinen Dank, {name}. Jetzt, da der Geist zur Ruhe gekomm'n is', kann ich meine Arbeit fortsetz'n.\n\nIhr habt wieder einmal bewies'n, dass ich mich auf Euch verlass'n kann. Ich verrate Euch das größte Geheimnis über Sternmoos.\n\nEs klingt verrückt, aber Ihr müsst's einfach ausprobier'n. Damit es der Pflanze gutgeht, müsst Ihr mit ihr sprech'n, sing'n, summ'n oder was Ähnliches, bevor Ihr sie pflückt. Ich weiß nich' warum, aber seit ich damit angefang'n hab, sind vor meinen Augen ein oder zwei neue Blüten entstand'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[51479] = { id = 51479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unverderbten", description = "Diese Welt ist... nicht, wie ich erwartet hatte.\n\nEs wird Zeit, Euren Kriegshäuptling zu treffen, {name}.\n\nEs gibt keinen Grund, es herauszuzögern.\n\nWir können später unsere Wunden lecken, wenn wir ein Dach über dem Kopf haben.", sourceObjective = "Kehrt zu Ji Feuerpfote in der Botschaft von Orgrimmar zurück, um das Ende dieser Geschichte zu hören.", completion = "Wie ich sehe, habt Ihr ein neues Gesicht dabei, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[51480] = { id = 51480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesige Ankerkrautkapsel", description = "Bei Eurer ganzen Sammelei seid Ihr bisher noch nie auf eine Ankerkrautkapsel dieser Größe gestoßen. Was auch immer der Grund für ihr außergewöhnliches Wachstum sein mag, es ließe sich sicher viel daraus lernen.\n\nIhr müsst an Jahden denken und fragt Euch, ob in dem Buch, das Ihr vorhin beschafft habt, vielleicht etwas darüber stehen könnte.", sourceObjective = "Bringt die riesige Ankerkrautkapsel zu Jahden Fla.\n\nBereitgestellter Gegenstand:", completion = "Hmm... Die sieht echt außergewöhnlich groß aus, aber selbst in dem Buch steht nix über 'ne riesige Samenkapsel. Ich muss da mal drüber nachdenk'n...", sourceObjectiveStatus = "unverified-source-field" }
quests[51481] = { id = 51481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Ankerkrautkapseln", description = "Ihr müsst mir 'ne Handvoll reife Ankerkrautkapseln besorg'n.\n\nDie riesige Samenkapsel is' zwar riesig, aber sie is' trotzdem immer noch 'ne Samenkapsel. Wenn wir die aufschneid'n und unsre Beobachtungen notier'n, könn' wir mehr über die kleineren normalen Samenkapseln erfahr'n und ganz einfach seh'n, wie ihre Anatomie funktioniert.\n\nIhr müsst mir also mehr von diesen reifen Ankerkrautkapseln besorg'n. Wenn meine Theorie stimmt, dann ham wir am Ende wertvolle Aufzeichnungen für die Zukunft.", sourceObjective = "Sammelt 9 reife Ankerkrautkapseln von Ankerkraut.", progress = "Ich bin gerade mit meinen Notizen zu der riesigen Samenkapsel fertig geword'n. Habt Ihr die andren Samenkapseln, die ich zum Vergleich brauch?", completion = "Ich weiß immer noch nich' genau, wie das Ding so groß geword'n is', aber ich glaub fast, das war 'n Geschenk von den Loa.\n\nAllerdings is' mir beim Aufschneid'n von der großen Kapsel aufgefall'n, dass die vermeintlichen dicken Wände am Äußeren von der Kapsel tatsächlich 'ne separate Kammer voller Samen war'n! Seht Ihr? Wenn man die Haut von 'ner normalen Kapsel vorsichtig ritzt und abzieht, kann man zusätzliche Samen sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[51482] = { id = 51482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach weiterem Wissen", description = "Das Ankerkraut gehört zu den heiligst'n Pflanzen auf dieser Insel. In den Legenden heißt es, es wär 'n Geschenk von den Loa gewes'n und dass es alles Mögliche bewirk'n kann... Es soll sogar Gliedmaße nachwachs'n lass'n oder unsterblich mach'n.\n\nWenn Ihr aber wiss'n wollt, wozu das Kraut wirklich in der Lage is' und wie man's erntet, dann müsst Ihr die Antworten anderswo such'n. \n\nDie Geister sag'n, dass es 'n Buch gibt, in dem alles drinsteht, was Ihr wiss'n wollt. Sucht tief im Inneren vom Kronsteiganwesen danach.\n\nDie Geister verlang'n dafür, dass Ihr das tötet, was den Riss in der Geisterwelt verursacht.", sourceObjective = "Besorgt die Abhandlung über Ankerkraut aus dem Kronsteiganwesen.", progress = "Habt Ihr das Buch besorgt?", completion = "Das Ding is' ja in 'nem furchtbar schlechten Zustand. Is' da schon so viel Blut drauf gewes'n, als Ihr es gefund'n habt?\n\n<Es vergeht eine kleine Weile, während Jahden durch die Seiten blättert.>\n\nHmm... Genau lässt sich das an den Bildern nich' erkenn', aber es sieht so aus, als würd'n sich die Samenkapseln öffnen, wenn die Pflanze gestört wird.\n\nWenn sie aber erst an den Wurzeln abgeschnitt'n wird, geht der Wasservorrat verlor'n, der zum Öffnen und Schließ'n der Hülsen gebraucht wird. Also beginnt einfach unten und arbeitet Euch dann hoch. So solltet Ihr 'ne bessere Ernte erhalt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51483] = { id = 51483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition der Dunkeleisenzwerge", description = "Ihr habt uns wirklich stolz gemacht, {name}. Ich habe von Eurer Tapferkeit an der Oberfläche von Azeroth gehört.\n\nKehrt zum Berg zurück. Wir haben dort etwas Besonderes für Euch.", sourceObjective = "Trefft Moira Thaurissan in der Schattenschmiede.", completion = "Die Dunkeleisenzwerge hatten es in dieser Welt nie leicht. Aber durch Champions wie Euch an ihrer Seite lernen unsere Verbündeten den Mut kennen, der in unseren Herzen brennt.\n\nGenug geplaudert! Nehmt diese Rüstung und lasst uns mit einem kühlen Gebräu auf Euren Mut anstoßen!", sourceObjectiveStatus = "unverified-source-field" }
quests[51484] = { id = 51484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition der Mag'har", description = "Ihr habt zahllose Schlachten in ganz Azeroth geschlagen. Ihr habt sowohl unseren Verbündeten als auch unseren Feinden gezeigt, wer die Mag'har sind.\n\nKehrt nach Orgrimmar zurück. Dort werde ich Euch für Eure Unterstützung meines Volkes ehren.", sourceObjective = "Trefft Oberanführerin Geya'rah in Orgrimmar.", completion = "Obwohl wir Draenor verloren haben, werden wir unsere angestammte Heimat niemals vergessen... und auch nicht die tapferen Brüder und Schwestern, die im Kampf um unsere Freiheit ihr Leben verloren haben.\n\nEure Siege in Azeroth beweisen eindrucksvoll, dass unser Volk einen Platz in der Horde verdient hat. Es ist mir eine Ehre, Euch dieses Symbol unserer stolzen Ahnenreihe zu verleihen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51485] = { id = 51485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Horde", description = "Die Mag'har stehen vor einer neuen Zukunft, {class}.\n\nDraenor ist gefallen. Wir wissen nicht, ob wir jemals wieder unsere Heimat erblicken werden. Aber jetzt ist nicht die Zeit für Trauer um unsere Vergangenheit.\n\nWir nehmen unser Schicksal selbst in die Hand. Orgrimmar ist jetzt unsere Heimat und wir müssen uns in diesem Land einen Namen machen!\n\nZeigt den Verbündeten in der Horde, was es bedeutet, zu den Mag'har zu gehören. Trefft Euch mit dem Botschafter in der Botschaft des Kriegshäuptlings und beginnt dann Euren Siegeszug durch Azeroth.\n\nKraft und Ehre, {name}!", sourceObjective = "Trefft Euch mit Botschafter Schwarzwacht in der Botschaft von Orgrimmar.", completion = "Seid Ihr der Neue? Dann soll ich Euch willkommen heißen. Hier, nehmt diesen Brief.\n\n<Schwarzwacht seufzt entnervt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[51486] = { id = 51486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Allianz", sourceObjective = "Trefft Euch mit Botschafter Moorgard in der Botschaft von Sturmwind.", completion = "Ah, da seid Ihr ja, {name}! Wir haben Euch betrach– äh, erwartet!", sourceObjectiveStatus = "unverified-source-field" }
quests[51487] = { id = 51487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Antworten", description = "Als ich noch ein Kind war, hatte Carsten immer so einen Spruch: \"Die schönsten Gesichter sind die freundlichen.\" Das hat mir sehr geholfen, Besucher aus aller Welt kennenzulernen, die durch Boralus gereist sind.\n\nBefragen wir doch ein paar der Verantwortlichen hier. Vielleicht erzählen sie uns ja etwas über die Flotte, wenn wir sie nur freundlich genug fragen!", sourceObjective = "Fragt Schwester Adrianna, Bruder Drees und Schwester Celicia nach Informationen zu der verschwundenen Flotte.", completion = "Bis jetzt hatten wir kein Glück, aber ich glaube, wir machen Fortschritte.", sourceObjectiveStatus = "unverified-source-field" }
quests[51488] = { id = 51488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archiviertes Wissen", description = "Mir scheint, dieser Bruder Alen, von dem wir immer wieder hören, könnte vielleicht etwas wissen. \n\nZumindest hoffe ich das. Hier scheinen alle irgendwie etwas... ausweichend zu sein.\n\nIch glaube, ich habe ein paar Archivare in das südliche Kloster gehen sehen. Wenn wir ihnen folgen, finden wir bestimmt auch Alen.", sourceObjective = "Fragt Bruder Alen nach Informationen zu der verschwundenen Flotte.", progress = "Dieser Ort ist deutlich größer, als er aussieht!", completion = "Ich will nicht lange genug hierbleiben, um mitzuerleben, ob er nun recht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[51489] = { id = 51489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zu gehen", description = "Ha! Ich hab doch gewusst, dass die Flotte nicht einfach verschwunden ist!\n\nAber das ist für uns vielleicht eine Nummer zu groß. Verschwinden wir von hier, bevor die Lage noch außer Kontrolle gerät.\n\nSturmherz kann uns von hier aus ins Sturmsangtal bringen. Im Augenblick bringt es jedenfalls nichts, sich an die Tradition zu klammern, stimmt's?", sourceObjective = "Reist auf Sturmherz ins Sturmsangtal.", completion = "Was ist hier los?!", sourceObjectiveStatus = "unverified-source-field" }
quests[51490] = { id = 51490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzprobleme", description = "Sie haben das gesamte Tal gesperrt! Kein Wunder, dass sich so viele Leute über den Handel mit dem Markt von Brennadam beschwert haben.\n\nWir müssen etwas dagegen unternehmen. Diese Menschen müssen doch ihren Lebensunterhalt verdienen!\n\nIhr müsst für mich hier als Ehrenkadett einspringen, {name}. Sagt diesen Grobianen, sie sollen die Straße wieder öffnen!", sourceObjective = "Überzeugt die Miliz des Hauses Sturmsang, die Blockade aufzuheben.", completion = "Gute Arbeit! Jetzt können diese anständigen Leute endlich wieder ein normales Leben führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51491] = { id = 51491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unheilsdorn" }
quests[51492] = { id = 51492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulververschwörung", description = "Großmutter hat allen Aufgaben gegeben, um unser einst friedliches Nest wieder auf Vordermann zu bringen.\n\nIch weiß aber nicht, was ich tun soll. Die Ratten sind in unsere Lager eingedrungen und fressen alles, was ihnen vor die Zähne kommt.\n\nIch habe eine von ihnen angestupst, damit sie verschwindet, aber dann lief ihr plötzlich Schaum aus dem Mund und sie ist explodiert! \n\nIch glaube, ich weiß, wohin das ganze Schießpulver verschwunden ist...\n\nWürdet Ihr es Marie bringen, wenn Ihr etwas davon findet?", sourceObjective = "Sammelt 100 Einheiten Schießpulver von explosiven Ratten.", progress = "Konntet Ihr etwas Pulver finden, mein Lieber?", completion = "Vielen lieben Dank. Ich wünschte, Karl wäre auch so fleißig.", sourceObjectiveStatus = "unverified-source-field" }
quests[51494] = { id = 51494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bluttor" }
quests[51495] = { id = 51495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die alte Rotana" }
quests[51496] = { id = 51496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterste Schubloade" }
quests[51497] = { id = 51497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexte Ausbildung" }
quests[51498] = { id = 51498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kulturelle Bedeutung", description = "Mir is' aufgefall'n, dass Ihr Euch jetz' beim Sammeln von Pflanzen geschickter anstellt. Mir is' aber auch aufgefall'n, dass Ihr die Blüten und Blätter bloß als Ware behandelt. Die Pflanzenwelt von diesen Inseln hat 'ne lange Geschichte und is' für unsere Kultur ziemlich wichtig.\n\nGeht runter zum Hafen von Zandalar und fragt 'n paar Männer und Frauen in der Stadt, was der Meeresstängel ihnen bedeutet. Lernt von uns und ich sorg dafür, dass es sich für Euch lohnt.", sourceObjective = "Erfahrt von den Leuten im Hafen von Zandalar mehr über die Bedeutung der Meeresstängel.", completion = "Die Meeresstängel ham 'ne einzigartige magische Eigenschaft, durch die sie ihre Blüten selbst dann mit Wasser versorg'n, wenn man sie abschneidet.\n\nSeeleute geb'n ihren Liebsten 'ne Blüte und behalt'n den Stängel. Falls sie dann über Bord geh'n, tötet das Salzwasser die Blüte. Was Ihr da in den Händen habt, is' kein einfacher Stecken, sondern steht für das Leben von einem Familienmitglied.\n\nWas Eure Lektion angeht: Im Gegensatz zu den meisten magischen Pflanzen is' die meiste magische Essenz hier nich' etwa in den Blättern oder Blüten enthalt'n, sondern im Stängel.", sourceObjectiveStatus = "unverified-source-field" }
quests[51500] = { id = 51500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königsruh: Der Waffenmeister ist wieder auf den Beinen" }
quests[51501] = { id = 51501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königsruh: Fatale Fehlfunktion" }
quests[51502] = { id = 51502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königsruh: Königswächter" }
quests[51503] = { id = 51503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andenken sammeln", description = "Es gibt da was, das ich niemandem sonst anvertrau'n kann, und ich glaub, Ihr würdet die Aufgabe mit dem nötigen Respekt angeh'n.\n\n'ne alte Freundin is' heut zu mir gekomm' und hatte 'ne verwelkte Meeresstängelblüte bei sich. Ihr Mann gehörte zur Besatzung von 'nem Schiff, das vor der Küste von Nazmir gesunk'n is'. Ich weiß nich', ob es die Naga, die Allianz oder 'ne Sturmböe war, aber sie hat gesagt, dass sie keine Rache will... Sie will bloß mit der Sache abschließ'n.\n\nWenn Ihr ihr 'n Andenken an ihren verstorbenen Gatten bring'n könntet, verrat ich Euch alles, was ich über Meeresstängel weiß.", sourceObjective = "Durchsucht die mit Seetang bewachsenen Stellen, um ein Andenken an den verlorenen Seefahrer zu finden.", progress = "Habt Ihr schon die Gelegenheit gehabt, die Wrackteile zu durchsuch'n?", completion = "Ich kann Euch gar nich' genug dafür dank'n.\n\nDer Tod scheint dieses Land ständig heimzusuch'n, aber er schmerzt nich' so sehr, wenn wir die Verstorbenen noch in unsren Erinnerungen festhalt'n könn'n.\n\nWas Eure Lektion angeht, kann ich Euch eigentlich bloß noch 'nen einfachen Rat geb'n: Um das meiste aus jedem Meeresstängel rauszuhol'n, zieht ihn vorsichtig aus'm Sand und reißt dann die Wurzeln ab, anstatt den Stängel einfach von der Pflanze abzuschneid'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51504] = { id = 51504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kekslieferung", description = "Liebchen, bevor Ihr aufbrecht, muss ich Euch noch um einen weiteren Gefallen bitten.\n\nBitte nehmt diese Kekse für Karl mit.\n\nWas für eine Großmutter wäre ich wohl, wenn ich ihm nicht auch welche gebacken hätte?!\n\nEine ziemlich furchtbare! Und das soll mir niemand nachsagen können!", sourceObjective = "Bringt die Schachtel mit Keksen zu Karl Fürbittshafen im Fichtenhain.", progress = "Rieche ich da etwa Kekse!?", completion = "Kekse? Für mich?! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[51505] = { id = 51505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stachelrattenmatriarchin" }
