quests[51512] = { id = 51512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gallenzahnmutter" }
quests[51513] = { id = 51513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zalazanes Rückkehr", description = "{name}, ich hab Eure Hilfe noch nie so dringend gebraucht wie heute. Mein Haus wird angegriff'n.\n\nIch hab's grad selbst erst gehört. Meister Gadrin ruft nach Hilfe. Zalazane is 'n alter Feind der Dunkelspeere und er is' zu den Echoinseln zurückgekehrt. Als ob das nicht genug wär, hat er auch noch 'ne Armee der Toten dabei.\n\nZalazane is 'n Verräter, der viele Dunkelspeere getötet und ihre Seelen besudelt hat. Kommt Ihr mit mir und helft, ihn zu besieg'n? Wir könn' das Schiff vom Hafen von Zandalar aus nehm'n.", sourceObjective = "Erreicht Meister Gadrin auf den Echoinseln.", completion = "Ihr... habt die Zandalari mitgebracht?", sourceObjectiveStatus = "unverified-source-field" }
quests[51514] = { id = 51514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gescheiterter Handel", description = "Es komm' immer mehr seelenlose Untote. Die sin' erstaunlich stark. Als Zalazane das letzte Mal auf dieser Erde wandelte, war'n sie viel schwächer.\n\nBitte helft uns, ihren Angriff zurückzuschlag'n.", sourceObjective = "Tötet 20 geistlose Trolle auf der Dunkelspeerinsel.", completion = "Tote sollt'n tot bleib'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51515] = { id = 51515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für Vol'jin", description = "Wenn wir Zalazane endgültig töt'n woll'n, brauch'n wir was, das diesen Geist verwund'n kann.\n\nVol'jins Gleve könnt genau das richtige Werkzeug hierfür sein.\n\nZalazane spukt in der Gegend herum, wo er vor so vielen Jahren gefall'n is'. Rokhan und Talanji sind schon aufgebroch'n, um sich ihm entgegenzustell'n.\n\nGeht und tötet Zalazane und durchbohrt den Geist mit der Gleve, bevor er entwisch'n kann. Lasst uns hoff'n, dass Vol'jins Gleve mächtig genug is', um diesen schrecklichen Gegner zu töt'n.", sourceObjective = "Tötet Zalazane.", completion = "Die Klinge... sie leuchtet. Das hat die vorher noch nie gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[51516] = { id = 51516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Die Asche eines Kriegshäuptlings", description = "Ich hab mir in letzter Zeit Einiges von den Dunkelspeeren abgeguckt. Eigentlich hab ich sie schon im Stillen bewundert, seit ich 'n kleines Mädchen war. Vor allem Vol'jins Widerstand gegen Zuls erbarmungslose Befehle hat mich beeindruckt.\n\nVol'jin war 'n Kriegshäuptling der Horde, Häuptling der Dunkelspeere und 'n Vollbluttroll, wie es sonst nur wenige gibt.\n\nSeine Asche sollte an einem Ort geehrt werd'n, der Königinnen und Königen würdig is'.\n\nNehmt die Asche und meinen Segen mit nach Atal'Dazar und ehrt Euren verstorbenen Kriegshäuptling, wie es seiner würdig is'.", sourceObjective = "Bringt Vol'jins Asche nach Atal'Dazar.", completion = "Wir beide müss'n uns unterhalt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51517] = { id = 51517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr schuldet mir einen Geist", description = "Das lasst Ihr aber nich' hier rumsteh'n.\n\nIn meinem Haus tanzt der alte Vol'jin nich'. Ich hab seinen Geist schon ewig nich' mehr geseh'n.\n\nDurch seine Abwesenheit ist das Band zeriss'n, mit dem ich Zalazane unter Kontrolle gehalt'n hab.\n\nIch will, dass Ihr diese schwere Urne nehmt und zu meiner Nekropole bringt.\n\nVol'jin und ich werd'n uns auf meinem Grund und Boden von Angesicht zu Angesicht treff'n.", sourceObjective = "Bringt Vol'jins Urne zu Bwonsamdi in Nazmir.\n\nBereitgestellter Gegenstand:", completion = "Darauf hab ich schon 'ne ganze Weile gewartet. War schon lange fällig, hee hee... Wartet 'nen Moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[51518] = { id = 51518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Geist", description = "Es is' höchste Zeit, dass wir beide uns über Vol'jins verschwund'nen Geist unterhalt'n.\n\nDas hat nichts mit einfachen Geschäft'n oder Übergangsriten zu tun. Geister verschwind'n nich' so einfach.\n\nIhr habt 'n paar Freunde, die Euch helfen werd'n, Vol'jins Geist aufzuspür'n. Wer mit ihm zu Lebzeiten befreundet war, sollte die Kraft ham, ihn auch im Tode zu find'n. Und wenn nich', wird Talanji Euch helf'n.\n\nGeht zu Talanjis Schiff im Hafen von Zandalar. Das is' das ramponierte Schiff, auf dem Ihr hergekomm' seid. Ihr werdet eine kleine Séance abhalten.", sourceObjective = "Sprecht mit Prinzessin Talanji im Hafen von Zandalar.", completion = "Ich bin hier, weil Meister Gadrin und Rokhan mich um Hilfe gebeten hab'n, und aus Dankbarkeit für ihre und Eure Taten bin ich bereit, ihnen zu helf'n.\n\nNICH', weil Bwonsamdi drauf bestand'n hat.\n\nWenn er seine eignen Geister nicht im Auge behalt'n kann, ist das sein Problem, nich' meins.", sourceObjectiveStatus = "unverified-source-field" }
quests[51519] = { id = 51519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterruf", description = "Wir werd'n hierfür bis weit in die Schattenlande vordringen müss'n. Wenn Bwonsamdi Vol'jin aus den Aug'n verlor'n hat, dann hat der sich entweder irgendwo verirrt oder er versteckt sich.\n\nWie dem auch sei, ich hoffe, dass das Band zwisch'n ihm und den versammelten Dunkelspeer'n dabei hilft, ihn zu uns zu hol'n.\n\nBleibt in der Nähe und unterbrecht das Ritual nich', wenn es begonnen hat.", sourceObjective = "Beobachtet Talanjis Ritual.", completion = "Hallo, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[51520] = { id = 51520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit für die Gefallenen", description = "Gerechtigkeit für die Söhne un' Töchter verlor'ner Loa. Gerechtigkeit für das Herz von Zandalar. G'huun muss getötet werd'n, un' denen, die es seh'n müss'n, soll 'n Zeich'n für seinen Tod präsentiert werd'n.\n\nNehmt meine Gleve un' stoßt sie in den Kadaver des Ungeheuers. Dann soll Talanji das ihren Leut'n zeig'n.\n\nFried'n soll in den Herz'n der Zandalari beginnen.", sourceObjective = "Taucht Vol'jins Gleve in das Blut von G'huuns Kadaver.", progress = "Wahnsinn un' Dunkelheit sin' auf der andren Seite. Die Schmerz'n von so viel'n sin' gewaltig.", completion = "Das war 'n Feind, der die Trolle seit viel'n Generationen bedroht hat. Wir hab'n vielleicht nich' immer gewusst, wie der heißt, aber wir hab'n seinen Fluch gespürt.\n\nHeut habt Ihr tausend'n Generationen von Trollen Gerechtigkeit gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[51521] = { id = 51521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahre Anführerin von Zandalar", description = "Jetzt nehmt meine Gleve und geht mit Talanji. Sie soll Euren Sieg ihren Leut'n präsentier'n. Die Trolle soll'n Gerechtigkeit kennenlern' un' die Stärke eines Anführers.", sourceObjective = "Zeigt Vol'jins Gleve gemeinsam mit Talanji der Bevölkerung von Zandalar.", completion = "Talanji is' die wahre Anführerin von Zandalar, auch wenn sie's bezweifelt. Mit 'n wenig Hilfe wird sie die Regentschaft von ihrem Vater in den Schatt'n stell'n.\n\nHabt Dank für den Moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[51526] = { id = 51526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Kriegsfürsten", description = "Die Reißzahnfeste ist unsere wertvollste Stellung in Kul Tiras. Wir dürfen sie nicht verlieren!\n\nDer Kriegshäuptling hat dem Obersten Kriegsfürst Cromush die Verantwortung für unsere Verstärkung übertragen. Ihr habt Befehl, Euch so schnell wie möglich bei ihm zu melden.", sourceObjective = "Meldet Euch beim Obersten Kriegsfürsten Cromush in Zuldazar.", completion = "Los, macht Euch kampfbereit, {name}. Eine Schlacht wartet auf uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[51527] = { id = 51527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharfrichter Schwartz" }
