quests[51530] = { id = 51530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebetene Gäste" }
quests[51532] = { id = 51532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Sturm", description = "{name}, die Front ruft!\n\nGestern Nacht haben wir erfahren, dass die Streitmacht von Rexxar in der Reißzahnfeste im Sturmsangtal von einer Armee aus Kul Tiras umzingelt wurde und ein Angriff kurz bevorsteht.\n\nSobald Ihr Eure Sachen gepackt habt, sprecht Ihr sofort mit Schreckensadmiralin Segelriss und macht Euch auf den Weg. Wir dürfen keine Zeit verlieren!", sourceObjective = "Sprecht mit Admiralin Segelriss und segelt zum Tiragardesund.", completion = "Mir ist schleierhaft, mit welchen bösen Zaubern die Kul Tiraner unsere Schiffe belegt haben, aber unsere Männer werden in diesem Moment gegen die Küste gedrängt und wir können sie nicht evakuieren!\n\nKeine Zeit für komplizierte Pläne, wir müssen sofort etwas unternehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[51533] = { id = 51533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol'jins Gleve", description = "Wenn Ihr geg'n wen kämpft, der Bwonsamdis eisigem Griff entkomm' is', wie's bei Zalazane der Fall is', dann braucht man Waffen, die ihn auch wirklich verwund'n könn'.\n\nSucht in der Dunkelspeerfeste nach Vol'jins Gleve.\n\nIhr Band mit dem Geist von Vol'jin sollte stark genug sein, um uns in diesem Kampf zu helf'n.", sourceObjective = "Beschafft Vol'jins Gleve.", progress = "Habt Ihr die Gleve gefund'n?", completion = "Das Band zwisch'n Vol'jin und Zalazane bestand aus Magie und war hart ausgehandelt.\n\nDas Band zwisch'n Vol'jin und dieser Waffe war ebenfalls stark. Damit könn' wir vielleicht endlich diesen Geist vernicht'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51534] = { id = 51534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Brennadam", sourceObjective = "Sammelt 1 geborgene Kugeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[51535] = { id = 51535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Veteranen", description = "{name}, uns haben Nachrichten aus Orgrimmar erreicht. Etrigg hat eine Versammlung einberufen. Er sagt, es sei sehr wichtig. Hat einen Brief für Euch hiergelassen.\n\nIhr lasst ihn besser nicht warten, sonst stirbt er noch an Altersschwäche, bevor er Euch erzählen kann, was er will.", sourceObjective = "Trefft Euch mit Etrigg bei der Botschaft von Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[51536] = { id = 51536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Jagd", description = "Es sieht so aus, als ob die Magie, die diese Kul Tiraner auf unsere Schiffe gewirkt haben, nachlässt. Ich bin mir aber sicher, dass das, was unseren Schiffen widerfahren ist, nur der Anfang ist.\n\nBegebt Euch zur Küste. Wir müssen die Überlebenden kontaktieren und herausfinden, wie unser Gegner aufgestellt ist.", sourceObjective = "Sucht in der Meereswacht nach Überlebenden.", completion = "Habt Dank!\n\nDiese Menschen haben heute einen großen Fehler gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[51538] = { id = 51538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht aus der Tiefe", description = "Der Rat der Zanchuli wurde von einer dunklen Seele unterwandert, die sich mit Königin Azshara verbünden will.\n\nEinige wurden von Furcht oder Gier überwältigt und haben sich ihr angeschlossen, andere haben sich einfach von ihren Lügen blenden lassen.\n\nWir sterben einer nach dem anderen. Bald wird es keinen Widerstand mehr geben.\n\nDie Motive von Azshara sind von einer undurchsichtigen Dunkelheit verschleiert. Sie begibt sich an einen Ort, von dem es für sie keine Rückkehr gibt.\n\nIch würde sie ja bemitleiden, aber sie hat zu viele meiner Anhänger getötet...\n\nWenn die Zeit gekommen ist, werde ich sie in Stücke reißen.", sourceObjective = "Unterrichtet die Sucher von Grals Warnung.", completion = "Anscheinend sind die Naga gefährlicher geworden und nicht mehr bloß ein lästiges Ärgernis. Das sind wirklich düstere Zeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[51539] = { id = 51539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterrichtet die Horde!", description = "Das war das Werk eines Mitglieds des Rats der Zanchuli.\n\nSie haben ihre eigenen Brüder, die Anhänger von Gral, für Azshara geopfert. Das ist gewissenloser Frevel!\n\nSie schwächen das Fundament und wollen so das Königreich stürzen.\n\nEin Mitglied Eures Volkes muss unser direkter Kontakt zum König sein. Ansonsten können wir niemandem vertrauen.", sourceObjective = "Warnt Baine vor dem Verrat.", completion = "Es war klug von Euch, mir das zu bringen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[51540] = { id = 51540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Situation", description = "<Diese Kiste ist ins Wasser gefallen. Sie enthält Bomben, die konstruiert wurden, um große mechanische Geräte auszuschalten.>\n\n<Wenn wir mehr davon hätten, könnten wir versuchen, den Riffbrecher der Venture Company zu zerstören.>", sourceObjective = "Sammelt 5 Botbrecherbomben.", progress = "Ihr werdet mehr dieser Bomben brauchen, wenn wir den Riffbrecher zerstören wollen.", completion = "Viele Schlachten werden von denen gewonnen, die die Initiative ergreifen und spontan eine Chance nutzen. Ihr habt eine ausgezeichnete Chance entdeckt. \n\nIhr solltet sie jetzt nutzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[51541] = { id = 51541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bogenlicht" }
quests[51542] = { id = 51542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneesturz" }
quests[51543] = { id = 51543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzlinge im Schnee", description = "Seid auf der Hut, <Festländer/Festländerin>, hier lauern überall Gefahren.\n\nEine dieser gefährlichen Kreaturen, Grünpirscher, war einst unser Verbündeter. Aber er hat in seinem verderbten, hirnlosen Zorn beinahe meinen Bruder und mich getötet, als wir jemandem in der Wildnis helfen wollten. Es gibt da etwas, das uns weiterhelfen könnte, aber ich muss mich um die Wunden meines Bruders kümmern und kann es nicht selbst beschaffen.\n\nBitte geht Ihr auf den Berghang und zieht ein paar Setzlinge aus der Erde. Die Pflanzen hier sind gesund und haben tiefe Wurzeln. Es wird also keine einfache Aufgabe.", sourceObjective = "Sammelt 6 Bergsetzlinge.", progress = "Habt Ihr die Bergsetzlinge gefunden, die ich brauche?", completion = "Danke, dass Ihr so schnell zurückgekehrt seid. Das sind ganz junge Pflanzen, voller lebensspendender Energie. Ein nötiges Opfer, um die Verderbnis zu läutern.\n\nGebt mir einen Moment, bis ich den Talisman fertig habe.", sourceObjectiveStatus = "unverified-source-field" }
